export const ELECTROSTATIQUE_SRIT_L1_CHAPTERS: CurriculumChapter[] = [
  // ==========================================================================
  // CHAPITRE 1 : OUTILS MATHÉMATIQUES ET CHARGE ÉLECTRIQUE
  // ==========================================================================
  {
    id: 'lmd_srit_l1_estat_ch1',
    subjectId: 'lmd_electrostatique',
    gradeLevel: 'lmd_srit_l1',
    semesters: [1],
    order: 1,
    officialVolumeHours: 8,
    contentVersion: 2,
    source: SOURCE,
    title: 'Outils mathématiques et charge électrique',
    summary: 'Champs scalaires et vectoriels, coordonnées, gradient, flux et angle solide ; charge électrique, loi de Coulomb et principe de superposition.',
    points: [
      makePoint({
        id: 'lmd_srit_l1_estat_ch1_p1',
        order: 1,
        title: 'Champs, coordonnées, gradient et flux',
        summary: 'Les outils de calcul de tout le cours : champ scalaire et vectoriel, coordonnées cylindriques et sphériques, gradient, flux d’un champ et angle solide.',
        conceptExplanation: r`L’électrostatique décrit des grandeurs définies en chaque point de l’espace. Un **champ scalaire** associe un nombre à chaque point (le potentiel $V$), un **champ vectoriel** associe un vecteur (le champ $\vec{E}$). Pour les calculer, on choisit le système de coordonnées adapté à la symétrie (cartésiennes, cylindriques ou sphériques), on dérive avec le **gradient** et on intègre à travers une surface avec le **flux**.`,
        formulas: [
          { name: 'Gradient en cartésiennes', formula: r`\overrightarrow{\text{grad}}\,V = \frac{\partial V}{\partial x}\vec{u}_x + \frac{\partial V}{\partial y}\vec{u}_y + \frac{\partial V}{\partial z}\vec{u}_z` },
          { name: 'Gradient en polaires (plan méridien)', formula: r`\overrightarrow{\text{grad}}\,V = \frac{\partial V}{\partial r}\vec{u}_r + \frac{1}{r}\frac{\partial V}{\partial \theta}\vec{u}_\theta` },
          { name: 'Flux d’un champ à travers une surface', formula: r`\Phi = \iint_S \vec{E}\cdot d\vec{S}` },
        ],
        keyRule: r`Choisis toujours les coordonnées qui suivent la symétrie : sphère → sphériques $(r,\theta,\varphi)$, fil ou cylindre → cylindriques $(\rho,\varphi,z)$.`,
        workedExample: {
          title: 'Gradient d’un potentiel en coordonnées polaires',
          statement: r`Dans un plan méridien, le potentiel vaut $V(r,\theta) = \frac{k\cos\theta}{r^2}$ (avec $k$ constante). Calcule les composantes du champ $\vec{E} = -\overrightarrow{\text{grad}}\,V$.`,
          methodSteps: [
            r`Composante radiale : $E_r = -\frac{\partial V}{\partial r} = -k\cos\theta \cdot \left(-\frac{2}{r^3}\right) = \frac{2k\cos\theta}{r^3}$.`,
            r`Composante orthoradiale : $E_\theta = -\frac{1}{r}\frac{\partial V}{\partial \theta} = -\frac{1}{r}\cdot\frac{-k\sin\theta}{r^2} = \frac{k\sin\theta}{r^3}$.`,
            r`On reconnaît le champ d’un dipôle : il décroît en $\frac{1}{r^3}$.`,
          ],
          conclusion: r`$E_r = \frac{2k\cos\theta}{r^3}$ et $E_\theta = \frac{k\sin\theta}{r^3}$.`,
        },
        structuredSteps: [
          step(1, 'definition', 'Champs', 'Champ scalaire et champ vectoriel',
            r`Un **champ scalaire** donne un nombre en chaque point : température, altitude, potentiel électrique $V(M)$. Un **champ vectoriel** donne un vecteur (direction, sens, norme) en chaque point : vitesse du vent, champ électrique $\vec{E}(M)$, champ magnétique $\vec{B}(M)$. Les deux sont liés : le champ électrostatique dérive du potentiel.`,
            qcm('lmd_srit_l1_estat_ch1_p1_ex1',
              'Parmi ces grandeurs physiques définies en chaque point d’une salle, laquelle forme un champ VECTORIEL ?',
              ['La température de l’air en chaque point', 'Le potentiel électrique en chaque point', 'La vitesse de l’air (courant d’air) en chaque point', 'La pression de l’air en chaque point'],
              2, 'La vitesse de l’air a une direction et un sens en plus de sa valeur : c’est un champ vectoriel. Température, potentiel et pression sont de simples nombres : ce sont des champs scalaires.',
              'Cherche la grandeur qui a une direction.')),
          step(2, 'propriete', 'Coordonnées', 'Coordonnées cylindriques et sphériques',
            r`En **sphériques** $(r,\theta,\varphi)$, l’élément de volume vaut $d\tau = r^2\sin\theta\,dr\,d\theta\,d\varphi$ et l’élément de surface d’une sphère de rayon $R$ vaut $dS = R^2\sin\theta\,d\theta\,d\varphi$. En **cylindriques** $(\rho,\varphi,z)$ : $d\tau = \rho\,d\rho\,d\varphi\,dz$ et la surface latérale d’un cylindre vaut $dS = \rho\,d\varphi\,dz$.`,
            qcm('lmd_srit_l1_estat_ch1_p1_ex2',
              r`On intègre l’élément de surface $dS = R^2\sin\theta\,d\theta\,d\varphi$ d’une sphère de rayon $R$ avec $\theta$ de $0$ à $\pi$ et $\varphi$ de $0$ à $2\pi$. Quel résultat obtient-on ?`,
              [r`$2\pi R^2$`, r`$4\pi R^2$`, r`$\frac{4}{3}\pi R^3$`, r`$\pi R^2$`],
              1, r`$\int_0^{\pi}\sin\theta\,d\theta = 2$ et $\int_0^{2\pi}d\varphi = 2\pi$, donc $S = R^2 \times 2 \times 2\pi = 4\pi R^2$ : l’aire de la sphère.`,
              r`Calcule séparément $\int_0^\pi \sin\theta\,d\theta$.`),
            { formula: { name: 'Éléments de volume', formula: r`d\tau_{\text{sph}} = r^2\sin\theta\,dr\,d\theta\,d\varphi \quad ; \quad d\tau_{\text{cyl}} = \rho\,d\rho\,d\varphi\,dz` } }),
          step(3, 'methode', 'Gradient', 'Calculer un gradient en cartésiennes',
            r`Le gradient d’un champ scalaire $V$ est le vecteur de ses dérivées partielles. Il est orienté vers les valeurs **croissantes** de $V$, et sa norme mesure la rapidité de la variation. Méthode : dérive $V$ par rapport à $x$ (en gardant $y$ et $z$ constants), puis par rapport à $y$, puis par rapport à $z$.`,
            qcm('lmd_srit_l1_estat_ch1_p1_ex3',
              r`Soit le champ scalaire $V(x,y,z) = 3x^2 y$. Que vaut $\overrightarrow{\text{grad}}\,V$ au point $(x=1, y=2, z=0)$ ?`,
              [r`$(12\,;\,3\,;\,0)$`, r`$(6\,;\,3\,;\,0)$`, r`$(12\,;\,6\,;\,0)$`, r`$(3\,;\,12\,;\,0)$`],
              0, r`$\frac{\partial V}{\partial x} = 6xy = 6\times1\times2 = 12$, $\frac{\partial V}{\partial y} = 3x^2 = 3$, $\frac{\partial V}{\partial z} = 0$. Donc $\overrightarrow{\text{grad}}\,V = (12\,;\,3\,;\,0)$.`,
              r`Dérive d’abord par rapport à $x$ en traitant $y$ comme une constante.`),
            { formula: { name: 'Gradient', formula: r`\overrightarrow{\text{grad}}\,V = \left(\frac{\partial V}{\partial x}\,;\,\frac{\partial V}{\partial y}\,;\,\frac{\partial V}{\partial z}\right)` } }),
          step(4, 'methode', 'Polaires', 'Le gradient en coordonnées polaires',
            r`Dans un plan méridien repéré en polaires $(r,\theta)$, le gradient a deux composantes : $\frac{\partial V}{\partial r}$ selon $\vec{u}_r$ et $\frac{1}{r}\frac{\partial V}{\partial\theta}$ selon $\vec{u}_\theta$. Le facteur $\frac{1}{r}$ vient de ce qu’un petit angle $d\theta$ correspond à un déplacement $r\,d\theta$. C’est le calcul demandé dans les devoirs pour un champ « à symétrie de révolution ».`,
            qcm('lmd_srit_l1_estat_ch1_p1_ex4',
              r`Le potentiel vaut $V(r,\theta) = \frac{k\cos\theta}{r^2}$ ($k$ constante). Quelle est la composante orthoradiale $E_\theta$ du champ $\vec{E} = -\overrightarrow{\text{grad}}\,V$ ?`,
              [r`$E_\theta = \frac{2k\cos\theta}{r^3}$`, r`$E_\theta = -\frac{k\sin\theta}{r^3}$`, r`$E_\theta = \frac{k\sin\theta}{r^2}$`, r`$E_\theta = \frac{k\sin\theta}{r^3}$`],
              3, r`$E_\theta = -\frac{1}{r}\frac{\partial V}{\partial\theta} = -\frac{1}{r}\times\frac{-k\sin\theta}{r^2} = \frac{k\sin\theta}{r^3}$. Le signe moins du gradient et la dérivée de $\cos\theta$ se compensent.`,
              r`N’oublie ni le facteur $\frac{1}{r}$ ni le signe moins de $\vec{E} = -\overrightarrow{\text{grad}}\,V$.`)),
          step(5, 'propriete', 'Flux', 'Flux d’un champ uniforme à travers une surface plane',
            r`Le **flux** mesure « la quantité de champ » qui traverse une surface orientée par son vecteur normal $\vec{n}$. Pour un champ uniforme $\vec{E}$ et une surface plane d’aire $S$ : $\Phi = E\,S\cos\alpha$, où $\alpha$ est l’angle entre $\vec{E}$ et la normale $\vec{n}$. Le flux est maximal quand le champ est perpendiculaire à la surface ($\alpha = 0$) et nul quand il est parallèle à la surface ($\alpha = 90°$). Unité : $\text{V}\cdot\text{m}$.`,
            qcm('lmd_srit_l1_estat_ch1_p1_ex5',
              r`Un champ uniforme $E = 200\text{ V/m}$ traverse une surface plane d’aire $S = 0{,}5\text{ m}^2$. L’angle entre $\vec{E}$ et la normale à la surface vaut $60°$. Que vaut le flux $\Phi$ ?`,
              [r`$100\text{ V}\cdot\text{m}$`, r`$86{,}6\text{ V}\cdot\text{m}$`, r`$50\text{ V}\cdot\text{m}$`, r`$0\text{ V}\cdot\text{m}$`],
              2, r`$\Phi = E\,S\cos\alpha = 200 \times 0{,}5 \times \cos 60° = 100 \times 0{,}5 = 50\text{ V}\cdot\text{m}$.`,
              r`$\cos 60° = 0{,}5$.`),
            { formula: { name: 'Flux d’un champ uniforme', formula: r`\Phi = \vec{E}\cdot\vec{S} = E\,S\cos\alpha` } }),
          step(6, 'piege', 'Angle solide', 'L’angle solide : 4π pour tout l’espace',
            r`L’**angle solide** $\Omega$ (en stéradians, sr) sous lequel on voit une surface depuis un point est l’aire découpée sur une sphère de rayon $1$ centrée en ce point : $d\Omega = \frac{dS\cos\alpha}{r^2}$. Piège classique : l’espace entier vaut $4\pi\text{ sr}$ (et non $2\pi$, qui est la valeur d’un angle plan complet en radians).`,
            qcm('lmd_srit_l1_estat_ch1_p1_ex6',
              r`Depuis un point $O$, on regarde un demi-espace (tout ce qui est d’un seul côté d’un plan infini passant par $O$). L’espace entier vaut $4\pi\text{ sr}$. Quel est l’angle solide de ce demi-espace ?`,
              [r`$\pi\text{ sr}$`, r`$2\pi\text{ sr}$`, r`$4\pi\text{ sr}$`, r`$\frac{\pi}{2}\text{ sr}$`],
              1, r`Le plan coupe la sphère unité en deux hémisphères égaux : $\Omega = \frac{4\pi}{2} = 2\pi\text{ sr}$.`,
              'Un plan passant par le centre coupe la sphère en deux moitiés.')),
        ],
      }),
      makePoint({
        id: 'lmd_srit_l1_estat_ch1_p2',
        order: 2,
        title: 'Charge électrique, loi de Coulomb et superposition',
        summary: 'Quantification de la charge, interaction entre deux charges ponctuelles, principe de superposition et distributions continues de charges.',
        conceptExplanation: r`La charge électrique est **quantifiée** (multiple de $e = 1{,}6\times10^{-19}\text{ C}$) et **conservée**. Deux charges ponctuelles exercent l’une sur l’autre une force portée par la droite qui les joint, proportionnelle au produit des charges et inversement proportionnelle au carré de la distance : c’est la **loi de Coulomb**. Avec plusieurs charges, les forces s’additionnent vectoriellement (**superposition**).`,
        formulas: [
          { name: 'Loi de Coulomb', formula: r`\vec{F}_{1\to2} = k\,\frac{q_1 q_2}{r^2}\,\vec{u}_{12} \quad ; \quad k = \frac{1}{4\pi\varepsilon_0} \approx 9\times10^{9}\text{ N}\cdot\text{m}^2\cdot\text{C}^{-2}`, note: r`$\varepsilon_0 \approx 8{,}85\times10^{-12}\text{ F/m}$` },
          { name: 'Charges élémentaires d’une distribution', formula: r`dq = \lambda\,d\ell \quad ; \quad dq = \sigma\,dS \quad ; \quad dq = \rho\,d\tau` },
        ],
        keyRule: 'La force de Coulomb est attractive entre charges de signes contraires et répulsive entre charges de même signe ; la force de 1 sur 2 est opposée à celle de 2 sur 1.',
        workedExample: {
          title: 'Point d’équilibre entre deux charges positives',
          statement: r`Une charge $q_A = +4\,\mu\text{C}$ est en $x = 0$ et une charge $q_B = +1\,\mu\text{C}$ en $x = 3\text{ m}$. Où placer une charge d’essai positive sur le segment pour qu’elle soit en équilibre ?`,
          methodSteps: [
            r`Entre les deux charges, les forces de $A$ et de $B$ sur la charge d’essai sont opposées : il suffit d’égaler leurs normes.`,
            r`$k\frac{4}{x^2} = k\frac{1}{(3-x)^2}$ donne $\frac{2}{x} = \frac{1}{3-x}$, soit $6 - 2x = x$.`,
            r`Donc $x = 2\text{ m}$ : le point d’équilibre est plus proche de la charge la plus faible.`,
          ],
          conclusion: r`Équilibre en $x = 2\text{ m}$.`,
        },
        visualSchema: { type: 'custom_svg', title: 'Loi de Coulomb : deux charges de même signe', svgContent: SVG_COULOMB },
        structuredSteps: [
          step(1, 'definition', 'Charge', 'Une charge quantifiée et conservée',
            r`Toute charge électrique est un multiple entier de la charge élémentaire : $q = n\,e$ avec $e = 1{,}6\times10^{-19}\text{ C}$. Un corps qui **perd** des électrons devient chargé **positivement** ; un corps qui en **gagne** devient négatif. Dans un système isolé, la charge totale se conserve.`,
            qcm('lmd_srit_l1_estat_ch1_p2_ex1',
              r`Une règle frottée perd $5\times10^{12}$ électrons ($e = 1{,}6\times10^{-19}\text{ C}$). Quelle est sa charge ?`,
              [r`$-8\times10^{-7}\text{ C}$`, r`$+3{,}2\times10^{-31}\text{ C}$`, r`$+8\times10^{-6}\text{ C}$`, r`$+8\times10^{-7}\text{ C}$`],
              3, r`$|q| = n\,e = 5\times10^{12}\times1{,}6\times10^{-19} = 8\times10^{-7}\text{ C}$. Elle a perdu des électrons : sa charge est positive, $q = +0{,}8\,\mu\text{C}$.`,
              'Perdre des charges négatives rend le corps positif.')),
          step(2, 'propriete', 'Coulomb', 'La loi de Coulomb',
            r`Deux charges ponctuelles $q_1$ et $q_2$ à la distance $r$ s’exercent des forces de même norme $F = k\frac{|q_1 q_2|}{r^2}$, avec $k = 9\times10^{9}\text{ N}\cdot\text{m}^2\cdot\text{C}^{-2}$. Les forces sont portées par la droite qui joint les charges.`,
            qcm('lmd_srit_l1_estat_ch1_p2_ex2',
              r`Deux charges $q_1 = 2\,\mu\text{C}$ et $q_2 = -3\,\mu\text{C}$ sont à $r = 0{,}3\text{ m}$ l’une de l’autre ($k = 9\times10^{9}$ SI). Quelle est la force entre elles ?`,
              [r`$0{,}6\text{ N}$, attractive`, r`$0{,}6\text{ N}$, répulsive`, r`$0{,}18\text{ N}$, attractive`, r`$1{,}8\text{ N}$, attractive`],
              0, r`$F = 9\times10^{9}\times\frac{2\times10^{-6}\times3\times10^{-6}}{0{,}3^2} = \frac{0{,}054}{0{,}09} = 0{,}6\text{ N}$. Les charges sont de signes contraires : la force est attractive.`,
              r`$r^2 = 0{,}09\text{ m}^2$ ; attention au carré de la distance.`),
            { formula: { name: 'Norme de la force de Coulomb', formula: r`F = k\,\frac{|q_1\,q_2|}{r^2}` } }),
          step(3, 'exemple', 'Ordre de grandeur', 'Force électrique contre gravitation',
            r`Entre deux protons, la force électrique est environ $10^{36}$ fois plus grande que l’attraction gravitationnelle : à l’échelle des atomes, la gravitation est négligeable. Le calcul : $\frac{F_e}{F_g} = \frac{k e^2}{G m_p^2}$ avec $G = 6{,}67\times10^{-11}$ SI et $m_p = 1{,}67\times10^{-27}\text{ kg}$.`,
            qcm('lmd_srit_l1_estat_ch1_p2_ex3',
              r`Pour deux protons ($e = 1{,}6\times10^{-19}\text{ C}$, $m_p = 1{,}67\times10^{-27}\text{ kg}$, $k = 9\times10^{9}$ SI, $G = 6{,}67\times10^{-11}$ SI), quel est l’ordre de grandeur du rapport $\frac{F_e}{F_g} = \frac{ke^2}{Gm_p^2}$ ?`,
              [r`$10^{6}$`, r`$10^{-36}$`, r`$10^{36}$`, r`$1$`],
              2, r`$ke^2 = 9\times10^{9}\times2{,}56\times10^{-38} \approx 2{,}3\times10^{-28}$ et $Gm_p^2 = 6{,}67\times10^{-11}\times2{,}79\times10^{-54} \approx 1{,}86\times10^{-64}$. Le rapport vaut environ $1{,}24\times10^{36}$.`,
              'Les deux forces varient en 1/r² : la distance disparaît du rapport.')),
          step(4, 'methode', 'Superposition', 'Plusieurs charges : on additionne les vecteurs',
            r`La force subie par une charge en présence de plusieurs autres est la **somme vectorielle** des forces exercées par chacune (principe de superposition). Méthode : calcule chaque force séparément, représente-la, puis additionne les vecteurs. Sur un axe, cherche le point où les forces se compensent en égalant les normes.`,
            qcm('lmd_srit_l1_estat_ch1_p2_ex4',
              r`Une charge $q_A = +4\,\mu\text{C}$ est en $x = 0$ et une charge $q_B = +1\,\mu\text{C}$ en $x = 3\text{ m}$. En quel point $x$ du segment une charge d’essai positive est-elle en équilibre ?`,
              [r`$x = 1\text{ m}$`, r`$x = 1{,}5\text{ m}$`, r`$x = 2{,}4\text{ m}$`, r`$x = 2\text{ m}$`],
              3, r`Il faut $\frac{4}{x^2} = \frac{1}{(3-x)^2}$, soit $\frac{2}{x} = \frac{1}{3-x}$, donc $6 - 2x = x$ et $x = 2\text{ m}$. Vérification : $\frac{4}{4} = \frac{1}{1}$.`,
              'Prends la racine carrée des deux membres de l’égalité.')),
          step(5, 'definition', 'Distributions', 'Distributions continues : λ, σ, ρ',
            r`À grande échelle, la charge est répartie de façon continue. Sur un fil, on utilise la **densité linéique** $\lambda$ (C/m) : $dq = \lambda\,d\ell$. Sur une surface, la **densité surfacique** $\sigma$ (C/m²) : $dq = \sigma\,dS$. Dans un volume, la **densité volumique** $\rho$ (C/m³) : $dq = \rho\,d\tau$. La charge totale s’obtient en intégrant.`,
            qcm('lmd_srit_l1_estat_ch1_p2_ex5',
              r`Un fil rectiligne de longueur $L = 2\text{ m}$ porte une charge uniformément répartie de densité linéique $\lambda = 5\text{ nC/m}$. Quelle est sa charge totale ?`,
              [r`$2{,}5\text{ nC}$`, r`$10\text{ nC}$`, r`$5\text{ nC}$`, r`$20\text{ nC}$`],
              1, r`$Q = \int_0^{L}\lambda\,d\ell = \lambda L = 5\times2 = 10\text{ nC}$.`,
              'Densité uniforme : la charge est densité × longueur.')),
          step(6, 'piege', 'Vecteurs', 'Ne jamais additionner les normes',
            r`Piège fréquent : additionner les **normes** des forces au lieu des **vecteurs**. Deux forces de $3\text{ N}$ perpendiculaires donnent une résultante de $3\sqrt{2} \approx 4{,}2\text{ N}$, pas $6\text{ N}$ ; deux forces opposées de $3\text{ N}$ donnent $0$. Projette toujours sur des axes avant d’additionner.`,
            qcm('lmd_srit_l1_estat_ch1_p2_ex6',
              r`Une charge subit deux forces électriques de même norme $F = 3\text{ N}$, perpendiculaires entre elles. Quelle est la norme de la force résultante ?`,
              [r`$3\sqrt{2} \approx 4{,}24\text{ N}$`, r`$6\text{ N}$`, r`$0\text{ N}$`, r`$9\text{ N}$`],
              0, r`Les forces sont perpendiculaires : $F_{\text{tot}} = \sqrt{3^2 + 3^2} = 3\sqrt{2} \approx 4{,}24\text{ N}$ (théorème de Pythagore).`,
              'Deux vecteurs perpendiculaires : utilise Pythagore.')),
        ],
      }),
    ],
  },

  // ==========================================================================
  // CHAPITRE 2 : CHAMP ET POTENTIEL ÉLECTROSTATIQUES
  // ==========================================================================
  {
    id: 'lmd_srit_l1_estat_ch2',
    subjectId: 'lmd_electrostatique',
    gradeLevel: 'lmd_srit_l1',
    semesters: [1],
    order: 2,
    officialVolumeHours: 14,
    contentVersion: 2,
    source: SOURCE,
    title: 'Champ et potentiel électrostatiques',
    summary: 'Champ créé par des charges ponctuelles et des distributions continues, symétries, potentiel et énergie, dipôle électrostatique, flux et théorème de Gauss.',
    points: [
      makePoint({
        id: 'lmd_srit_l1_estat_ch2_p1',
        order: 1,
        title: 'Le champ électrostatique et ses symétries',
        summary: 'Définition du champ, champ d’une charge ponctuelle, superposition, champ d’un anneau sur son axe, symétries et lignes de champ.',
        conceptExplanation: r`Une charge $q$ placée en un point $M$ subit la force $\vec{F} = q\,\vec{E}(M)$ : le **champ électrostatique** $\vec{E}$ décrit l’influence des autres charges, indépendamment de $q$. Il se calcule par superposition (somme ou intégrale des contributions). Les **symétries** de la distribution indiquent sa direction avant tout calcul (principe de Curie).`,
        formulas: [
          { name: 'Champ d’une charge ponctuelle', formula: r`\vec{E}(M) = k\,\frac{q}{r^2}\,\vec{u}_r \quad ; \quad \vec{F} = q'\,\vec{E}` },
          { name: 'Anneau de rayon R, sur son axe', formula: r`E(x) = \frac{kQ\,x}{(x^2 + R^2)^{3/2}}` },
        ],
        keyRule: 'Le champ électrostatique est contenu dans tout plan de symétrie de la distribution et perpendiculaire à tout plan d’antisymétrie.',
        workedExample: {
          title: 'Champ d’un anneau chargé sur son axe',
          statement: r`Un anneau de rayon $R = 0{,}3\text{ m}$ porte $Q = 10\text{ nC}$. Calcule le champ en un point de son axe à $x = 0{,}4\text{ m}$ du centre ($k = 9\times10^{9}$ SI).`,
          methodSteps: [
            r`Par symétrie de révolution, seule la composante selon l’axe subsiste : les composantes radiales se compensent deux à deux.`,
            r`$x^2 + R^2 = 0{,}16 + 0{,}09 = 0{,}25$, donc $(x^2+R^2)^{3/2} = 0{,}25^{3/2} = 0{,}125$.`,
            r`$E = \frac{9\times10^{9}\times10^{-8}\times0{,}4}{0{,}125} = \frac{36}{0{,}125} = 288\text{ V/m}$.`,
          ],
          conclusion: r`$E = 288\text{ V/m}$, dirigé selon l’axe, en s’éloignant de l’anneau.`,
        },
        structuredSteps: [
          step(1, 'definition', 'Champ', 'Le champ d’une charge ponctuelle',
            r`Une charge $q$ crée en un point $M$ à la distance $r$ un champ $\vec{E} = k\frac{q}{r^2}\vec{u}_r$, où $\vec{u}_r$ va de la charge vers $M$. Le champ « sort » d’une charge positive et « entre » dans une charge négative. Unité : $\text{V/m}$ (ou $\text{N/C}$).`,
            qcm('lmd_srit_l1_estat_ch2_p1_ex1',
              r`Une charge ponctuelle $q = 5\text{ nC}$ crée un champ en un point situé à $r = 0{,}3\text{ m}$ ($k = 9\times10^{9}$ SI). Quelle est la valeur de ce champ ?`,
              [r`$150\text{ V/m}$`, r`$1500\text{ V/m}$`, r`$500\text{ V/m}$`, r`$50\text{ V/m}$`],
              2, r`$E = k\frac{q}{r^2} = \frac{9\times10^{9}\times5\times10^{-9}}{0{,}09} = \frac{45}{0{,}09} = 500\text{ V/m}$.`,
              r`$9\times10^{9}\times5\times10^{-9} = 45$.`)),
          step(2, 'methode', 'Superposition', 'Champ de deux charges : additionner les vecteurs',
            r`Le champ total est la somme vectorielle des champs de chaque charge. Au milieu de deux charges **opposées** $+q$ et $-q$, les deux champs vont dans le même sens (du $+$ vers le $-$) : ils s’ajoutent. Au milieu de deux charges **égales**, ils se compensent : le champ est nul.`,
            qcm('lmd_srit_l1_estat_ch2_p1_ex2',
              r`Deux charges $+2\text{ nC}$ et $-2\text{ nC}$ sont distantes de $0{,}2\text{ m}$ ($k = 9\times10^{9}$ SI). Quel est le champ au milieu du segment qui les joint ?`,
              [r`$0\text{ V/m}$`, r`$3600\text{ V/m}$, dirigé vers la charge négative`, r`$1800\text{ V/m}$, dirigé vers la charge négative`, r`$3600\text{ V/m}$, dirigé vers la charge positive`],
              1, r`Chaque charge est à $0{,}1\text{ m}$ : $E_1 = E_2 = \frac{9\times10^{9}\times2\times10^{-9}}{0{,}01} = 1800\text{ V/m}$. Les deux champs pointent vers la charge négative : $E = 3600\text{ V/m}$.`,
              'Le champ s’éloigne du + et va vers le − : les deux vont dans le même sens.')),
          step(3, 'methode', 'Distribution', 'Champ d’un anneau sur son axe',
            r`Pour une distribution continue, on découpe en charges élémentaires $dq$ et on intègre. Pour un anneau de rayon $R$ portant $Q$, sur l’axe à la distance $x$ du centre, les composantes perpendiculaires à l’axe se compensent et il reste $E(x) = \frac{kQx}{(x^2+R^2)^{3/2}}$.`,
            qcm('lmd_srit_l1_estat_ch2_p1_ex3',
              r`Un anneau de rayon $R = 0{,}3\text{ m}$ porte $Q = 10\text{ nC}$ ($k = 9\times10^{9}$ SI). Quel est le champ sur son axe à $x = 0{,}4\text{ m}$ du centre, sachant que $E = \frac{kQx}{(x^2+R^2)^{3/2}}$ ?`,
              [r`$288\text{ V/m}$`, r`$562{,}5\text{ V/m}$`, r`$90\text{ V/m}$`, r`$1440\text{ V/m}$`],
              0, r`$x^2+R^2 = 0{,}25$ et $0{,}25^{3/2} = 0{,}125$. $kQx = 9\times10^{9}\times10^{-8}\times0{,}4 = 36$. Donc $E = \frac{36}{0{,}125} = 288\text{ V/m}$.`,
              r`$0{,}25^{3/2} = (\sqrt{0{,}25})^3 = 0{,}5^3$.`),
            { formula: { name: 'Anneau chargé (sur l’axe)', formula: r`E(x) = \frac{kQ\,x}{(x^2+R^2)^{3/2}}` } }),
          step(4, 'propriete', 'Symétries', 'Le principe de Curie appliqué à E',
            r`Les effets ont au moins les symétries des causes. Si un plan est un **plan de symétrie** de la distribution de charges, le champ en un point de ce plan est **contenu** dans ce plan. Si c’est un **plan d’antisymétrie** (charges opposées de part et d’autre), le champ y est **perpendiculaire**. Les invariances (translation, rotation) disent de quelles coordonnées le champ dépend.`,
            qcm('lmd_srit_l1_estat_ch2_p1_ex4',
              'Un point M appartient à un plan d’antisymétrie d’une distribution de charges (de part et d’autre du plan, les charges sont opposées). Que peut-on dire du champ électrostatique en M ?',
              ['Il est contenu dans le plan', 'Il est nul', 'Il est perpendiculaire au plan', 'On ne peut rien dire sans calcul'],
              2, 'Pour un plan d’antisymétrie, le champ électrostatique est perpendiculaire au plan (c’est le cas sur le plan médiateur d’un dipôle). Pour un plan de symétrie, il serait contenu dans le plan.',
              'Pense au plan médiateur entre +q et −q.')),
          step(5, 'definition', 'Lignes de champ', 'Lignes de champ',
            r`Une **ligne de champ** est une courbe tangente en chaque point au champ $\vec{E}$, orientée dans son sens. Elles partent des charges positives et finissent sur les charges négatives (ou à l’infini), ne se croisent jamais (le champ aurait deux directions) et sont plus serrées là où le champ est intense.`,
            qcm('lmd_srit_l1_estat_ch2_p1_ex5',
              'Laquelle de ces affirmations sur les lignes du champ électrostatique est FAUSSE ?',
              ['Elles sont tangentes au champ en chaque point', 'Deux lignes de champ peuvent se croiser en un point où le champ n’est pas nul', 'Elles partent des charges positives', 'Elles sont plus serrées là où le champ est plus intense'],
              1, 'En un point où le champ n’est pas nul, il a une seule direction : deux lignes ne peuvent pas s’y croiser. Les trois autres affirmations sont vraies.',
              'Que vaudrait la direction du champ au point de croisement ?')),
          step(6, 'piege', 'Centre de l’anneau', 'Au centre d’un anneau, le champ est nul',
            r`Piège : au centre d’un anneau uniformément chargé, chaque élément $dq$ est compensé par l’élément diamétralement opposé, donc $E(0) = 0$ (la formule donne bien $E = 0$ pour $x = 0$). Le champ sur l’axe est maximal à $x = \frac{R}{\sqrt{2}}$, puis décroît comme $\frac{kQ}{x^2}$ loin de l’anneau.`,
            qcm('lmd_srit_l1_estat_ch2_p1_ex6',
              r`Un anneau de rayon $R = 10\text{ cm}$ porte une charge $Q = 5\text{ nC}$ uniformément répartie. Que vaut le champ électrostatique exactement en son centre ?`,
              [r`$\frac{kQ}{R^2} = 4500\text{ V/m}$`, r`$\frac{kQ}{2R^2}$`, r`$0\text{ V/m}$`, 'Il est infini'],
              2, r`Au centre, les contributions des éléments diamétralement opposés s’annulent deux à deux : $E = 0$. La formule $E = \frac{kQx}{(x^2+R^2)^{3/2}}$ donne aussi $0$ pour $x = 0$.`,
              'Regarde deux petits morceaux d’anneau diamétralement opposés.')),
        ],
      }),
      makePoint({
        id: 'lmd_srit_l1_estat_ch2_p2',
        order: 2,
        title: 'Potentiel électrostatique, énergie et dipôle',
        summary: 'Potentiel d’une charge ponctuelle, relation E = −grad V, énergie potentielle et travail, surfaces équipotentielles, dipôle électrostatique.',
        conceptExplanation: r`Le champ électrostatique dérive d’un **potentiel** : $\vec{E} = -\overrightarrow{\text{grad}}\,V$. Le potentiel est un nombre (plus simple à additionner qu’un vecteur) défini à une constante près ; on le prend nul à l’infini. Une charge $q$ au potentiel $V$ possède l’énergie potentielle $E_p = qV$. Le **dipôle** (deux charges opposées très proches) est le modèle des molécules polaires et des antennes.`,
        formulas: [
          { name: 'Potentiel d’une charge ponctuelle', formula: r`V(r) = k\,\frac{q}{r} \quad (V(\infty) = 0)` },
          { name: 'Relation champ-potentiel', formula: r`\vec{E} = -\overrightarrow{\text{grad}}\,V \quad ; \quad dV = -\vec{E}\cdot d\vec{\ell}` },
          { name: 'Dipôle (moment p = qa)', formula: r`V = \frac{k\,p\cos\theta}{r^2} \quad ; \quad E_r = \frac{2kp\cos\theta}{r^3} \quad ; \quad E_\theta = \frac{kp\sin\theta}{r^3}` },
        ],
        keyRule: 'Le champ est perpendiculaire aux surfaces équipotentielles et dirigé vers les potentiels décroissants.',
        workedExample: {
          title: 'Énergie gagnée par un électron accéléré',
          statement: r`Un électron ($q = -1{,}6\times10^{-19}\text{ C}$) part sans vitesse d’un point $A$ au potentiel $V_A = 0$ et arrive en $B$ au potentiel $V_B = 100\text{ V}$. Quelle énergie cinétique a-t-il gagnée ?`,
          methodSteps: [
            r`Travail de la force électrique : $W_{A\to B} = q(V_A - V_B) = -1{,}6\times10^{-19}\times(0 - 100) = 1{,}6\times10^{-17}\text{ J}$.`,
            r`Théorème de l’énergie cinétique : $\Delta E_c = W_{A\to B} = 1{,}6\times10^{-17}\text{ J}$.`,
            r`En électronvolts : $1\text{ eV} = 1{,}6\times10^{-19}\text{ J}$, donc $\Delta E_c = 100\text{ eV}$.`,
          ],
          conclusion: r`L’électron gagne $1{,}6\times10^{-17}\text{ J}$, soit $100\text{ eV}$.`,
        },
        structuredSteps: [
          step(1, 'definition', 'Potentiel', 'Le potentiel d’une charge ponctuelle',
            r`Une charge $q$ crée à la distance $r$ le potentiel $V(r) = k\frac{q}{r}$ (en volts), choisi nul à l’infini. Pour plusieurs charges, les potentiels s’**additionnent algébriquement** (ce sont des nombres, pas des vecteurs), ce qui simplifie beaucoup les calculs.`,
            qcm('lmd_srit_l1_estat_ch2_p2_ex1',
              r`Une charge ponctuelle $q = 4\text{ nC}$ crée un potentiel en un point situé à $r = 0{,}2\text{ m}$ ($k = 9\times10^{9}$ SI, $V(\infty) = 0$). Quelle est la valeur de ce potentiel ?`,
              [r`$900\text{ V}$`, r`$72\text{ V}$`, r`$36\text{ V}$`, r`$180\text{ V}$`],
              3, r`$V = k\frac{q}{r} = \frac{9\times10^{9}\times4\times10^{-9}}{0{,}2} = \frac{36}{0{,}2} = 180\text{ V}$.`,
              'Le potentiel varie en 1/r (pas en 1/r²).')),
          step(2, 'propriete', 'E = −grad V', 'Du potentiel au champ',
            r`Le champ est l’opposé du gradient du potentiel : $\vec{E} = -\overrightarrow{\text{grad}}\,V$. Sur un axe : $E_x = -\frac{dV}{dx}$. Inversement, $V_A - V_B = \int_A^B \vec{E}\cdot d\vec{\ell}$ : la circulation du champ ne dépend pas du chemin suivi (champ conservatif).`,
            qcm('lmd_srit_l1_estat_ch2_p2_ex2',
              r`Sur un axe, le potentiel vaut $V(x) = 50x^2 - 20x$ (en volts, $x$ en mètres). Que vaut la composante $E_x$ du champ en $x = 1\text{ m}$ ?`,
              [r`$+80\text{ V/m}$`, r`$-80\text{ V/m}$`, r`$+30\text{ V/m}$`, r`$-30\text{ V/m}$`],
              1, r`$E_x = -\frac{dV}{dx} = -(100x - 20)$. En $x = 1$ : $E_x = -(100 - 20) = -80\text{ V/m}$.`,
              r`Dérive $V$, puis n’oublie pas le signe moins.`)),
          step(3, 'methode', 'Énergie', 'Travail et énergie potentielle électrique',
            r`Une charge $q$ au potentiel $V$ a l’énergie potentielle $E_p = qV$. Quand elle va de $A$ à $B$, la force électrique travaille : $W_{A\to B} = q(V_A - V_B)$. Avec le théorème de l’énergie cinétique, on trouve la vitesse gagnée. Unité pratique : l’électronvolt, $1\text{ eV} = 1{,}6\times10^{-19}\text{ J}$.`,
            qcm('lmd_srit_l1_estat_ch2_p2_ex3',
              r`Un électron ($q = -1{,}6\times10^{-19}\text{ C}$) va d’un point $A$ au potentiel $V_A = 0$ à un point $B$ au potentiel $V_B = 100\text{ V}$. Quel est le travail de la force électrique ?`,
              [r`$+1{,}6\times10^{-17}\text{ J}$`, r`$-1{,}6\times10^{-17}\text{ J}$`, r`$+1{,}6\times10^{-21}\text{ J}$`, r`$0\text{ J}$`],
              0, r`$W = q(V_A - V_B) = (-1{,}6\times10^{-19})\times(0 - 100) = +1{,}6\times10^{-17}\text{ J}$ : le travail est moteur, l’électron accélère (il gagne $100\text{ eV}$).`,
              'Attention aux deux signes moins : celui de la charge et celui de (0 − 100).')),
          step(4, 'propriete', 'Équipotentielles', 'Surfaces équipotentielles et sens du champ',
            r`Une **surface équipotentielle** réunit les points de même potentiel. Le champ y est toujours **perpendiculaire** (aucun travail en restant sur l’équipotentielle) et il pointe vers les **potentiels décroissants**. Pour une charge ponctuelle, les équipotentielles sont des sphères centrées sur la charge.`,
            qcm('lmd_srit_l1_estat_ch2_p2_ex4',
              r`Deux équipotentielles planes parallèles sont aux potentiels $V_1 = 300\text{ V}$ et $V_2 = 100\text{ V}$. Comment est orienté le champ électrostatique entre elles ?`,
              ['Parallèle aux équipotentielles', 'Perpendiculaire aux équipotentielles, de V₂ vers V₁', 'Perpendiculaire aux équipotentielles, de V₁ vers V₂', 'Le champ est nul entre elles'],
              2, 'Le champ est perpendiculaire aux équipotentielles et va vers les potentiels décroissants : de 300 V (V₁) vers 100 V (V₂).',
              'Le champ « descend » les potentiels.')),
          step(5, 'methode', 'Dipôle', 'Le champ d’un dipôle loin des charges',
            r`Un dipôle est formé de $-q$ et $+q$ distantes de $a$, de moment dipolaire $\vec{p} = q\,\overrightarrow{AB}$ (du $-$ vers le $+$). Loin du dipôle ($r \gg a$), on obtient par développement limité : $V = \frac{kp\cos\theta}{r^2}$, d’où $E_r = \frac{2kp\cos\theta}{r^3}$ et $E_\theta = \frac{kp\sin\theta}{r^3}$. Le champ décroît en $\frac{1}{r^3}$, plus vite que celui d’une charge seule.`,
            qcm('lmd_srit_l1_estat_ch2_p2_ex5',
              r`Un dipôle de moment $p = 10^{-12}\text{ C}\cdot\text{m}$ crée un champ en un point de son axe ($\theta = 0$) à $r = 0{,}1\text{ m}$. Avec $E_r = \frac{2kp\cos\theta}{r^3}$ et $k = 9\times10^{9}$ SI, que vaut le champ ?`,
              [r`$9\text{ V/m}$`, r`$1{,}8\text{ V/m}$`, r`$180\text{ V/m}$`, r`$18\text{ V/m}$`],
              3, r`Sur l’axe, $\cos\theta = 1$ et $E_\theta = 0$. $E = \frac{2\times9\times10^{9}\times10^{-12}}{10^{-3}} = \frac{0{,}018}{0{,}001} = 18\text{ V/m}$.`,
              r`$r^3 = 0{,}1^3 = 10^{-3}\text{ m}^3$.`),
            { formula: { name: 'Dipôle électrostatique (r ≫ a)', formula: r`V = \frac{k\,p\cos\theta}{r^2}` } }),
          step(6, 'piege', 'Couple', 'Dipôle dans un champ uniforme : un couple, pas de force',
            r`Dans un champ **uniforme** $\vec{E}_0$, les forces sur $+q$ et $-q$ sont opposées : la force totale est nulle, mais il reste un **couple** $\vec{\Gamma} = \vec{p}\wedge\vec{E}_0$, de norme $pE_0\sin\alpha$. Il fait tourner le dipôle jusqu’à l’équilibre **stable** $\vec{p}$ parallèle à $\vec{E}_0$ ($\alpha = 0$) ; l’équilibre $\alpha = \pi$ est instable.`,
            qcm('lmd_srit_l1_estat_ch2_p2_ex6',
              r`Un dipôle de moment $p = 4\times10^{-12}\text{ C}\cdot\text{m}$ est placé dans un champ uniforme $E_0 = 5\times10^{4}\text{ V/m}$, son moment faisant un angle $\alpha = 30°$ avec le champ. Quel est le moment du couple subi ?`,
              [r`$2\times10^{-7}\text{ N}\cdot\text{m}$`, r`$10^{-7}\text{ N}\cdot\text{m}$`, r`$1{,}73\times10^{-7}\text{ N}\cdot\text{m}$`, r`$0\text{ N}\cdot\text{m}$ (la force totale est nulle)`],
              1, r`$\Gamma = pE_0\sin\alpha = 4\times10^{-12}\times5\times10^{4}\times0{,}5 = 10^{-7}\text{ N}\cdot\text{m}$. La force totale est nulle, mais pas le couple.`,
              r`$\sin 30° = 0{,}5$.`)),
        ],
      }),
      makePoint({
        id: 'lmd_srit_l1_estat_ch2_p3',
        order: 3,
        title: 'Flux et théorème de Gauss',
        summary: 'Énoncé du théorème de Gauss, choix de la surface de Gauss, sphère chargée, fil infini, plan infini et plan épais chargé en volume.',
        conceptExplanation: r`Le **théorème de Gauss** relie le flux du champ à travers une surface **fermée** à la charge intérieure : $\oint \vec{E}\cdot d\vec{S} = \frac{Q_{\text{int}}}{\varepsilon_0}$. Avec une distribution très symétrique (sphère, cylindre, plan), on choisit une surface de Gauss sur laquelle le champ a une norme constante et est perpendiculaire à la surface : le flux devient un simple produit $E \times S$.`,
        formulas: [
          { name: 'Théorème de Gauss', formula: r`\oint_S \vec{E}\cdot d\vec{S} = \frac{Q_{\text{int}}}{\varepsilon_0}` },
          { name: 'Fil infini (densité λ)', formula: r`E = \frac{\lambda}{2\pi\varepsilon_0\,r} = \frac{2k\lambda}{r}` },
          { name: 'Plan infini (densité σ)', formula: r`E = \frac{\sigma}{2\varepsilon_0}` },
        ],
        keyRule: 'Le théorème de Gauss est toujours vrai, mais il ne permet de calculer E que si la symétrie rend E constant sur la surface choisie.',
        workedExample: {
          title: 'Plan épais chargé en volume (sujet de devoir)',
          statement: r`La région $-a \le x \le a$ est chargée uniformément (densité $\rho$), le reste est vide. Calcule le champ en tout point.`,
          methodSteps: [
            r`Symétries : invariance par translation selon $y$ et $z$, plan $x = 0$ de symétrie. Donc $\vec{E} = E(x)\vec{u}_x$ avec $E(-x) = -E(x)$.`,
            r`Surface de Gauss : cylindre d’axe $Ox$, de section $S$, entre $-x$ et $+x$. Flux : $2E(x)S$.`,
            r`Pour $|x| \le a$ : $2E S = \frac{\rho\,2xS}{\varepsilon_0}$, donc $E = \frac{\rho x}{\varepsilon_0}$. Pour $x \ge a$ : $2ES = \frac{\rho\,2aS}{\varepsilon_0}$, donc $E = \frac{\rho a}{\varepsilon_0}$.`,
          ],
          conclusion: r`$E = \frac{\rho x}{\varepsilon_0}$ dans le plan épais, $E = \pm\frac{\rho a}{\varepsilon_0}$ à l’extérieur : le champ est continu en $x = \pm a$.`,
        },
        visualSchema: { type: 'custom_svg', title: 'Surface de Gauss autour d’une charge', svgContent: SVG_GAUSS },
        structuredSteps: [
          step(1, 'propriete', 'Gauss', 'Le théorème de Gauss',
            r`Pour toute surface **fermée** $S$, le flux sortant du champ électrostatique vaut la charge intérieure divisée par $\varepsilon_0$ : $\oint_S \vec{E}\cdot d\vec{S} = \frac{Q_{\text{int}}}{\varepsilon_0}$. Les charges extérieures créent un flux total nul. Avec $\varepsilon_0 = 8{,}85\times10^{-12}\text{ F/m}$.`,
            qcm('lmd_srit_l1_estat_ch2_p3_ex1',
              r`Une surface fermée entoure une charge $Q_{\text{int}} = 8{,}85\text{ nC}$ ; une autre charge de $5\text{ nC}$ est à l’extérieur ($\varepsilon_0 = 8{,}85\times10^{-12}\text{ F/m}$). Quel est le flux du champ électrostatique sortant de la surface ?`,
              [r`$1000\text{ V}\cdot\text{m}$`, r`$1565\text{ V}\cdot\text{m}$`, r`$565\text{ V}\cdot\text{m}$`, r`$8{,}85\text{ V}\cdot\text{m}$`],
              0, r`Seule la charge intérieure compte : $\Phi = \frac{Q_{\text{int}}}{\varepsilon_0} = \frac{8{,}85\times10^{-9}}{8{,}85\times10^{-12}} = 1000\text{ V}\cdot\text{m}$.`,
              'La charge extérieure ne change pas le flux total.'),
            { formula: { name: 'Théorème de Gauss', formula: r`\Phi = \frac{Q_{\text{int}}}{\varepsilon_0}` } }),
          step(2, 'methode', 'Méthode', 'Choisir la bonne surface de Gauss',
            r`Méthode en 3 temps : (1) étudie les symétries pour connaître la direction de $\vec{E}$ et les variables dont il dépend ; (2) choisis une surface fermée qui suit la symétrie (sphère pour une distribution sphérique, cylindre coaxial pour un fil, « boîte » cylindrique traversant un plan) ; (3) calcule le flux et la charge intérieure, puis isole $E$.`,
            qcm('lmd_srit_l1_estat_ch2_p3_ex2',
              'Pour calculer avec le théorème de Gauss le champ créé par un fil rectiligne infini uniformément chargé, quelle surface de Gauss faut-il choisir ?',
              ['Une sphère centrée sur le fil', 'Un cube contenant une partie du fil', 'Un cylindre fermé coaxial au fil', 'Un plan contenant le fil'],
              2, 'Le champ d’un fil infini est radial et ne dépend que de la distance r au fil : sur un cylindre coaxial, il est constant et perpendiculaire à la surface latérale, et son flux est nul sur les deux disques.',
              'La surface doit suivre la symétrie cylindrique.')),
          step(3, 'exemple', 'Sphère', 'Sphère chargée en surface',
            r`Pour une sphère de rayon $R$ portant $Q$ en surface : à l’intérieur ($r < R$), la sphère de Gauss ne contient aucune charge, donc $E = 0$. À l’extérieur ($r > R$), $E \times 4\pi r^2 = \frac{Q}{\varepsilon_0}$, d’où $E = \frac{kQ}{r^2}$ : tout se passe comme si la charge était au centre.`,
            qcm('lmd_srit_l1_estat_ch2_p3_ex3',
              r`Une sphère de rayon $R = 0{,}1\text{ m}$ porte une charge $Q = 3\text{ nC}$ répartie sur sa surface ($k = 9\times10^{9}$ SI). Que vaut le champ à $r = 0{,}3\text{ m}$ du centre ?`,
              [r`$0\text{ V/m}$`, r`$2700\text{ V/m}$`, r`$90\text{ V/m}$`, r`$300\text{ V/m}$`],
              3, r`À l’extérieur, $E = \frac{kQ}{r^2} = \frac{9\times10^{9}\times3\times10^{-9}}{0{,}09} = \frac{27}{0{,}09} = 300\text{ V/m}$. (À l’intérieur, il serait nul.)`,
              'Le point est à l’extérieur de la sphère.')),
          step(4, 'propriete', 'Fil infini', 'Champ d’un fil infini',
            r`Pour un fil infini de densité $\lambda$, la surface de Gauss est un cylindre de rayon $r$ et de hauteur $h$. Flux : $E\times2\pi r h$ ; charge intérieure : $\lambda h$. D’où $E = \frac{\lambda}{2\pi\varepsilon_0 r} = \frac{2k\lambda}{r}$ : le champ décroît en $\frac{1}{r}$.`,
            qcm('lmd_srit_l1_estat_ch2_p3_ex4',
              r`Un fil infini porte une densité linéique $\lambda = 2\text{ nC/m}$. Quel est le champ à $r = 0{,}2\text{ m}$ du fil, sachant que $E = \frac{2k\lambda}{r}$ avec $k = 9\times10^{9}$ SI ?`,
              [r`$180\text{ V/m}$`, r`$90\text{ V/m}$`, r`$900\text{ V/m}$`, r`$360\text{ V/m}$`],
              0, r`$E = \frac{2\times9\times10^{9}\times2\times10^{-9}}{0{,}2} = \frac{36}{0{,}2} = 180\text{ V/m}$.`,
              r`$2\times9\times10^{9}\times2\times10^{-9} = 36$.`)),
          step(5, 'propriete', 'Plan infini', 'Champ d’un plan infini chargé',
            r`Pour un plan infini de densité surfacique $\sigma$, la surface de Gauss est une boîte cylindrique traversant le plan. Le flux sort par les deux bases : $2ES = \frac{\sigma S}{\varepsilon_0}$, d’où $E = \frac{\sigma}{2\varepsilon_0}$, **uniforme** de chaque côté. Entre deux plans portant $+\sigma$ et $-\sigma$, les champs s’ajoutent : $E = \frac{\sigma}{\varepsilon_0}$.`,
            qcm('lmd_srit_l1_estat_ch2_p3_ex5',
              r`Un plan infini porte une densité surfacique $\sigma = 1{,}77\times10^{-8}\text{ C/m}^2$ ($\varepsilon_0 = 8{,}85\times10^{-12}\text{ F/m}$). Quel est le champ qu’il crée, de chaque côté ?`,
              [r`$2000\text{ V/m}$`, r`$1000\text{ V/m}$`, r`$500\text{ V/m}$`, r`$100\text{ V/m}$`],
              1, r`$E = \frac{\sigma}{2\varepsilon_0} = \frac{1{,}77\times10^{-8}}{1{,}77\times10^{-11}} = 1000\text{ V/m}$, uniforme de chaque côté du plan.`,
              r`$2\varepsilon_0 = 1{,}77\times10^{-11}$.`)),
          step(6, 'piege', 'Continuité', 'Charge en volume : le champ est continu',
            r`Piège de devoir : le champ n’est **discontinu** qu’à la traversée d’une charge **surfacique** (saut de $\frac{\sigma}{\varepsilon_0}$). Pour un plan épais chargé **en volume** ($-a \le x \le a$, densité $\rho$), $E = \frac{\rho x}{\varepsilon_0}$ à l’intérieur et $E = \frac{\rho a}{\varepsilon_0}$ à l’extérieur : les deux valeurs se raccordent en $x = a$, le champ est **continu**.`,
            qcm('lmd_srit_l1_estat_ch2_p3_ex6',
              r`La région $-a \le x \le a$ est chargée uniformément en volume (densité $\rho$). On trouve $E = \frac{\rho x}{\varepsilon_0}$ pour $|x| \le a$ et $E = \frac{\rho a}{\varepsilon_0}$ pour $x \ge a$. Le champ est-il continu en $x = a$ ?`,
              ['Non, il saute de σ/ε₀', 'Oui : les deux expressions valent ρa/ε₀ en x = a', 'Non, il s’annule en x = a', 'On ne peut pas savoir sans la valeur de a'],
              1, r`En $x = a$, l’expression intérieure donne $\frac{\rho a}{\varepsilon_0}$, comme l’expression extérieure : le champ est continu. Il n’y a discontinuité qu’avec une charge surfacique.`,
              r`Remplace $x$ par $a$ dans la première expression.`)),
        ],
      }),
    ],
  },

  // ==========================================================================
  // CHAPITRE 3 : CONDUCTEURS EN ÉQUILIBRE ET CONDENSATEURS
  // ==========================================================================
  {
    id: 'lmd_srit_l1_estat_ch3',
    subjectId: 'lmd_electrostatique',
    gradeLevel: 'lmd_srit_l1',
    semesters: [1],
    order: 3,
    officialVolumeHours: 10,
    contentVersion: 2,
    source: SOURCE,
    title: 'Conducteurs en équilibre et condensateurs',
    summary: 'Propriétés d’un conducteur en équilibre, théorème de Coulomb, pouvoir des pointes, influence, capacité, condensateurs, associations et énergie.',
    points: [
      makePoint({
        id: 'lmd_srit_l1_estat_ch3_p1',
        order: 1,
        title: 'Le conducteur en équilibre électrostatique',
        summary: 'Champ nul à l’intérieur, potentiel uniforme, charges en surface, théorème de Coulomb, pouvoir des pointes, pression électrostatique et influence.',
        conceptExplanation: r`Dans un conducteur, les électrons libres se déplacent jusqu’à ce que plus aucune force ne s’exerce sur eux : à l’**équilibre**, le champ est nul à l’intérieur, le conducteur est **équipotentiel** et toute la charge se place en **surface**. Juste à l’extérieur, le champ est perpendiculaire à la surface et vaut $\frac{\sigma}{\varepsilon_0}$ (théorème de Coulomb).`,
        formulas: [
          { name: 'Théorème de Coulomb', formula: r`\vec{E}_{\text{ext}} = \frac{\sigma}{\varepsilon_0}\,\vec{n}` },
          { name: 'Pression électrostatique', formula: r`p = \frac{\sigma^2}{2\varepsilon_0}` },
        ],
        keyRule: 'Conducteur en équilibre : E = 0 à l’intérieur, V uniforme, charges en surface, E perpendiculaire à la surface juste à l’extérieur.',
        workedExample: {
          title: 'Deux sphères reliées par un fil',
          statement: r`Deux sphères conductrices éloignées, de rayons $R_1 = 1\text{ cm}$ et $R_2 = 5\text{ cm}$, sont reliées par un fil fin. Compare leurs densités surfaciques.`,
          methodSteps: [
            r`Reliées, elles ont le même potentiel : $\frac{kQ_1}{R_1} = \frac{kQ_2}{R_2}$.`,
            r`Avec $Q = \sigma\,4\pi R^2$ : $\sigma_1 R_1 = \sigma_2 R_2$.`,
            r`Donc $\frac{\sigma_1}{\sigma_2} = \frac{R_2}{R_1} = 5$.`,
          ],
          conclusion: 'La petite sphère a une densité 5 fois plus grande : c’est le pouvoir des pointes.',
        },
        structuredSteps: [
          step(1, 'definition', 'Équilibre', 'Les propriétés d’un conducteur en équilibre',
            r`À l’équilibre, les charges libres d’un conducteur ne bougent plus : le champ à l’intérieur est **nul** (sinon les électrons seraient mis en mouvement). Conséquences : le conducteur est **équipotentiel** ($\vec{E} = -\overrightarrow{\text{grad}}\,V = \vec{0}$) et, d’après Gauss, la charge intérieure est nulle : les charges sont **en surface**.`,
            qcm('lmd_srit_l1_estat_ch3_p1_ex1',
              'Une sphère métallique pleine porte une charge Q et est en équilibre électrostatique. Où se trouve cette charge ?',
              ['Uniformément répartie dans tout le volume', 'Concentrée au centre de la sphère', 'Entièrement à la surface de la sphère', 'Pour moitié au centre, pour moitié en surface'],
              2, 'Le champ est nul à l’intérieur du conducteur : d’après le théorème de Gauss, toute surface fermée intérieure contient une charge nulle. Toute la charge est donc à la surface.',
              'Applique Gauss à une petite surface fermée à l’intérieur du métal.')),
          step(2, 'propriete', 'Coulomb', 'Le théorème de Coulomb',
            r`Juste à l’extérieur d’un conducteur en équilibre, le champ est **perpendiculaire** à la surface (la surface est une équipotentielle) et vaut $E = \frac{\sigma}{\varepsilon_0}$, où $\sigma$ est la densité surfacique locale. On le démontre avec une petite boîte de Gauss qui traverse la surface.`,
            qcm('lmd_srit_l1_estat_ch3_p1_ex2',
              r`En un point de la surface d’un conducteur en équilibre, la densité surfacique vaut $\sigma = 8{,}85\times10^{-9}\text{ C/m}^2$ ($\varepsilon_0 = 8{,}85\times10^{-12}\text{ F/m}$). Quel est le champ juste à l’extérieur ?`,
              [r`$500\text{ V/m}$, parallèle à la surface`, r`$1000\text{ V/m}$, parallèle à la surface`, r`$500\text{ V/m}$, perpendiculaire à la surface`, r`$1000\text{ V/m}$, perpendiculaire à la surface`],
              3, r`$E = \frac{\sigma}{\varepsilon_0} = \frac{8{,}85\times10^{-9}}{8{,}85\times10^{-12}} = 1000\text{ V/m}$, perpendiculaire à la surface (et non $\frac{\sigma}{2\varepsilon_0}$ comme pour un plan isolé).`,
              'Ne confonds pas avec le plan infini isolé.'),
            { formula: { name: 'Théorème de Coulomb', formula: r`E = \frac{\sigma}{\varepsilon_0}` } }),
          step(3, 'exemple', 'Pointes', 'Le pouvoir des pointes',
            r`Deux sphères reliées ont le même potentiel, donc $\sigma_1 R_1 = \sigma_2 R_2$ : plus le rayon est petit, plus la densité de charge (et le champ) est grand. Les **pointes** concentrent les charges : c’est le principe du paratonnerre et l’origine des étincelles sur les objets pointus.`,
            qcm('lmd_srit_l1_estat_ch3_p1_ex3',
              r`Deux sphères conductrices éloignées, de rayons $R_1 = 1\text{ cm}$ et $R_2 = 5\text{ cm}$, sont reliées par un fil (même potentiel). Que vaut le rapport $\frac{\sigma_1}{\sigma_2}$ de leurs densités surfaciques ?`,
              [r`$\frac{1}{5}$`, r`$5$`, r`$25$`, r`$1$`],
              1, r`Même potentiel : $\frac{kQ_1}{R_1} = \frac{kQ_2}{R_2}$ avec $Q = 4\pi R^2\sigma$, d’où $\sigma_1 R_1 = \sigma_2 R_2$ et $\frac{\sigma_1}{\sigma_2} = \frac{R_2}{R_1} = 5$.`,
              r`Écris l’égalité des potentiels avec $Q = 4\pi R^2\sigma$.`)),
          step(4, 'propriete', 'Pression', 'La pression électrostatique',
            r`Les charges de surface sont repoussées par les autres charges : la surface du conducteur subit une force vers l’extérieur, comme une pression $p = \frac{\sigma^2}{2\varepsilon_0}$ (en pascals). Elle peut déformer des surfaces souples (bulle de savon chargée).`,
            qcm('lmd_srit_l1_estat_ch3_p1_ex4',
              r`Un conducteur porte en surface la densité $\sigma = 8{,}85\times10^{-6}\text{ C/m}^2$ ($\varepsilon_0 = 8{,}85\times10^{-12}\text{ F/m}$). Quelle est la pression électrostatique $p = \frac{\sigma^2}{2\varepsilon_0}$ ?`,
              [r`$4{,}4\text{ Pa}$`, r`$8{,}9\text{ Pa}$`, r`$1000\text{ Pa}$`, r`$0{,}5\text{ Pa}$`],
              0, r`$\sigma^2 = 7{,}83\times10^{-11}$ et $2\varepsilon_0 = 1{,}77\times10^{-11}$, donc $p = \frac{7{,}83\times10^{-11}}{1{,}77\times10^{-11}} \approx 4{,}4\text{ Pa}$.`,
              r`$(8{,}85\times10^{-6})^2 \approx 7{,}83\times10^{-11}$.`)),
          step(5, 'methode', 'Influence', 'Influence totale dans une cavité',
            r`Si une charge $q$ est placée dans la cavité d’un conducteur creux, une surface de Gauss dans le métal (où $E = 0$) montre que la paroi de la cavité porte exactement $-q$ : c’est l’**influence totale**. Si le conducteur est isolé et neutre, sa surface extérieure porte alors $+q$.`,
            qcm('lmd_srit_l1_estat_ch3_p1_ex5',
              r`Une charge $q = +5\text{ nC}$ est placée au centre de la cavité d’une sphère métallique creuse, isolée et initialement neutre. Quelles charges portent la paroi intérieure et la surface extérieure ?`,
              [r`$0\text{ nC}$ et $0\text{ nC}$`, r`$+5\text{ nC}$ et $-5\text{ nC}$`, r`$-5\text{ nC}$ et $0\text{ nC}$`, r`$-5\text{ nC}$ et $+5\text{ nC}$`],
              3, r`Influence totale : la paroi intérieure porte $-q = -5\text{ nC}$. Le conducteur étant neutre, la surface extérieure porte $+5\text{ nC}$ (conservation de la charge).`,
              'Le conducteur reste globalement neutre.')),
          step(6, 'piege', 'Cage de Faraday', 'Le champ est nul dans une cavité vide',
            r`Piège : dans une cavité **vide de charges** d’un conducteur en équilibre, le champ est **nul**, même si le conducteur est chargé ou placé dans un champ extérieur. C’est la **cage de Faraday** : elle protège les appareils électroniques et explique que l’on soit protégé de la foudre dans une voiture.`,
            qcm('lmd_srit_l1_estat_ch3_p1_ex6',
              r`Une boîte métallique fermée, vide de charges à l’intérieur, porte une charge $Q = 2\,\mu\text{C}$ sur sa surface extérieure et est placée dans un champ extérieur intense. Que vaut le champ électrostatique dans la cavité ?`,
              ['Il est nul', 'Il vaut σ/ε₀', 'Il est égal au champ extérieur', 'Il vaut kQ/r²'],
              0, 'Cavité vide dans un conducteur en équilibre : le potentiel y est uniforme, donc le champ est nul (cage de Faraday), quelles que soient la charge du conducteur et le champ extérieur.',
              'C’est le principe de protection d’une voiture pendant un orage.')),
        ],
      }),
      makePoint({
        id: 'lmd_srit_l1_estat_ch3_p2',
        order: 2,
        title: 'Capacité, condensateurs et énergie',
        summary: 'Capacité d’un conducteur, condensateurs plan, sphérique et cylindrique, associations série et parallèle, énergie emmagasinée et diélectrique.',
        conceptExplanation: r`La charge d’un conducteur isolé est proportionnelle à son potentiel : $Q = CV$, où $C$ (en farads) est sa **capacité**. Un **condensateur** est formé de deux conducteurs en influence totale (les armatures) portant $+Q$ et $-Q$ : $Q = C\,U$. Il stocke de l’énergie électrique, restituée lors de sa décharge (flash, alimentation de secours).`,
        formulas: [
          { name: 'Sphère isolée', formula: r`C = 4\pi\varepsilon_0 R` },
          { name: 'Condensateur plan', formula: r`C = \frac{\varepsilon_0\,\varepsilon_r\,S}{e}` },
          { name: 'Énergie stockée', formula: r`W = \frac{1}{2}CU^2 = \frac{Q^2}{2C}` },
        ],
        keyRule: 'En parallèle les capacités s’ajoutent ; en série ce sont les inverses des capacités qui s’ajoutent.',
        workedExample: {
          title: 'Capacité et énergie d’un condensateur plan',
          statement: r`Un condensateur plan a des armatures de surface $S = 0{,}02\text{ m}^2$ écartées de $e = 1\text{ mm}$ dans le vide. Calcule $C$ puis l’énergie stockée sous $U = 100\text{ V}$.`,
          methodSteps: [
            r`$C = \frac{\varepsilon_0 S}{e} = \frac{8{,}85\times10^{-12}\times0{,}02}{10^{-3}} = 1{,}77\times10^{-10}\text{ F} = 177\text{ pF}$.`,
            r`$W = \frac{1}{2}CU^2 = 0{,}5\times1{,}77\times10^{-10}\times10^{4} = 8{,}85\times10^{-7}\text{ J}$.`,
          ],
          conclusion: r`$C = 177\text{ pF}$ et $W \approx 0{,}89\,\mu\text{J}$.`,
        },
        visualSchema: { type: 'custom_svg', title: 'Condensateur plan', svgContent: SVG_PLAN_CONDENSATEUR },
        structuredSteps: [
          step(1, 'definition', 'Capacité', 'Capacité d’un conducteur isolé',
            r`Pour un conducteur isolé, $Q = C\,V$. Pour une sphère de rayon $R$ : $V = \frac{kQ}{R}$, donc $C = \frac{R}{k} = 4\pi\varepsilon_0 R$. Le farad est une unité énorme : on utilise le $\mu\text{F}$ ($10^{-6}$), le $\text{nF}$ ($10^{-9}$) et le $\text{pF}$ ($10^{-12}$).`,
            qcm('lmd_srit_l1_estat_ch3_p2_ex1',
              r`Quelle est la capacité d’une sphère conductrice isolée de rayon $R = 9\text{ cm}$, sachant que $C = 4\pi\varepsilon_0 R = \frac{R}{k}$ avec $k = 9\times10^{9}$ SI ?`,
              [r`$10\text{ pF}$`, r`$1\text{ pF}$`, r`$100\text{ pF}$`, r`$10\text{ nF}$`],
              0, r`$C = \frac{0{,}09}{9\times10^{9}} = 10^{-11}\text{ F} = 10\text{ pF}$.`,
              r`Convertis le rayon en mètres : $9\text{ cm} = 0{,}09\text{ m}$.`)),
          step(2, 'propriete', 'Plan', 'Le condensateur plan',
            r`Entre deux armatures planes de surface $S$ distantes de $e$ (petite devant leurs dimensions), le champ est uniforme : $E = \frac{\sigma}{\varepsilon_0}$ et $U = E\,e$. Avec $Q = \sigma S$, on obtient $C = \frac{\varepsilon_0 S}{e}$ : la capacité augmente avec la surface et diminue avec l’écartement.`,
            qcm('lmd_srit_l1_estat_ch3_p2_ex2',
              r`Un condensateur plan a des armatures de surface $S = 0{,}02\text{ m}^2$ écartées de $e = 1\text{ mm}$ dans le vide ($\varepsilon_0 = 8{,}85\times10^{-12}\text{ F/m}$). Quelle est sa capacité ?`,
              [r`$1{,}77\text{ pF}$`, r`$17{,}7\text{ pF}$`, r`$1{,}77\text{ nF}$`, r`$177\text{ pF}$`],
              3, r`$C = \frac{\varepsilon_0 S}{e} = \frac{8{,}85\times10^{-12}\times0{,}02}{10^{-3}} = 1{,}77\times10^{-10}\text{ F} = 177\text{ pF}$.`,
              r`$e = 1\text{ mm} = 10^{-3}\text{ m}$.`),
            { formula: { name: 'Condensateur plan (vide)', formula: r`C = \frac{\varepsilon_0 S}{e}` } }),
          step(3, 'propriete', 'Géométries', 'Condensateurs sphérique et cylindrique',
            r`Avec Gauss puis la circulation du champ entre les armatures : condensateur **sphérique** (rayons $R_1 < R_2$) : $C = \frac{4\pi\varepsilon_0 R_1 R_2}{R_2 - R_1}$ ; condensateur **cylindrique** (câble coaxial de longueur $L$) : $C = \frac{2\pi\varepsilon_0 L}{\ln(R_2/R_1)}$. Le câble coaxial des réseaux est un condensateur cylindrique.`,
            qcm('lmd_srit_l1_estat_ch3_p2_ex3',
              r`Un câble coaxial de longueur $L = 1\text{ m}$ a des rayons tels que $\frac{R_2}{R_1} = e$ (nombre d’Euler, $\ln e = 1$). Avec $C = \frac{2\pi\varepsilon_0 L}{\ln(R_2/R_1)}$ et $\varepsilon_0 = 8{,}85\times10^{-12}\text{ F/m}$, quelle est sa capacité ?`,
              [r`$8{,}85\text{ pF}$`, r`$55{,}6\text{ pF}$`, r`$27{,}8\text{ pF}$`, r`$111\text{ pF}$`],
              1, r`$C = 2\pi\varepsilon_0 L = 2\pi\times8{,}85\times10^{-12}\times1 \approx 5{,}56\times10^{-11}\text{ F} = 55{,}6\text{ pF}$.`,
              r`$\ln e = 1$ : il reste $2\pi\varepsilon_0 L$.`)),
          step(4, 'methode', 'Associations', 'Associer des condensateurs',
            r`En **parallèle** (même tension), les charges s’ajoutent : $C_{\text{éq}} = C_1 + C_2$. En **série** (même charge), les tensions s’ajoutent : $\frac{1}{C_{\text{éq}}} = \frac{1}{C_1} + \frac{1}{C_2}$, soit $C_{\text{éq}} = \frac{C_1 C_2}{C_1 + C_2}$ pour deux condensateurs. C’est l’inverse des résistances !`,
            qcm('lmd_srit_l1_estat_ch3_p2_ex4',
              r`Deux condensateurs de capacités $C_1 = 4\,\mu\text{F}$ et $C_2 = 12\,\mu\text{F}$ sont associés en SÉRIE. Quelle est la capacité équivalente ?`,
              [r`$16\,\mu\text{F}$`, r`$8\,\mu\text{F}$`, r`$3\,\mu\text{F}$`, r`$48\,\mu\text{F}$`],
              2, r`En série : $C_{\text{éq}} = \frac{C_1C_2}{C_1+C_2} = \frac{4\times12}{16} = 3\,\mu\text{F}$ (toujours plus petite que la plus petite capacité).`,
              'En série, la capacité équivalente est plus petite que chacune.')),
          step(5, 'propriete', 'Énergie', 'L’énergie stockée',
            r`Charger un condensateur demande un travail, stocké sous forme d’énergie électrique : $W = \frac{1}{2}CU^2 = \frac{Q^2}{2C} = \frac{1}{2}QU$. Cette énergie est localisée dans le champ, avec la densité volumique $w = \frac{1}{2}\varepsilon_0 E^2$.`,
            qcm('lmd_srit_l1_estat_ch3_p2_ex5',
              r`Un condensateur de capacité $C = 10\,\mu\text{F}$ est chargé sous une tension $U = 200\text{ V}$. Quelle énergie stocke-t-il ?`,
              [r`$0{,}2\text{ J}$`, r`$2\text{ mJ}$`, r`$0{,}4\text{ J}$`, r`$2\text{ J}$`],
              0, r`$W = \frac{1}{2}CU^2 = 0{,}5\times10^{-5}\times200^2 = 0{,}5\times10^{-5}\times4\times10^{4} = 0{,}2\text{ J}$.`,
              r`$200^2 = 4\times10^{4}$.`)),
          step(6, 'piege', 'Diélectrique', 'Avec un diélectrique, la capacité est multipliée par εr',
            r`Remplir l’espace entre les armatures avec un isolant de permittivité relative $\varepsilon_r$ multiplie la capacité : $C = \varepsilon_r C_0$. Piège : à **charge constante** (condensateur isolé), la tension est alors divisée par $\varepsilon_r$ ; à **tension constante** (relié au générateur), c’est la charge qui est multipliée par $\varepsilon_r$.`,
            qcm('lmd_srit_l1_estat_ch3_p2_ex6',
              r`Un condensateur plan a une capacité $C_0 = 50\text{ pF}$ dans le vide. On remplit entièrement l’espace entre ses armatures par un diélectrique de permittivité relative $\varepsilon_r = 3$. Quelle est sa nouvelle capacité ?`,
              [r`$16{,}7\text{ pF}$`, r`$53\text{ pF}$`, r`$50\text{ pF}$`, r`$150\text{ pF}$`],
              3, r`$C = \varepsilon_r C_0 = 3\times50 = 150\text{ pF}$ : le diélectrique augmente la capacité.`,
              r`La capacité est multipliée (et non divisée) par $\varepsilon_r$.`)),
        ],
      }),
    ],
  },

  // ==========================================================================
  // CHAPITRE 4 : MAGNÉTOSTATIQUE
  // ==========================================================================
  {
    id: 'lmd_srit_l1_estat_ch4',
    subjectId: 'lmd_electrostatique',
    gradeLevel: 'lmd_srit_l1',
    semesters: [1],
    order: 4,
    officialVolumeHours: 12,
    contentVersion: 2,
    source: SOURCE,
    title: 'Magnétostatique',
    summary: 'Champ magnétique créé par des courants (Biot et Savart), fil, spire, solénoïde, conservation du flux, théorème d’Ampère, forces de Laplace et interaction entre fils.',
    points: [
      makePoint({
        id: 'lmd_srit_l1_estat_ch4_p1',
        order: 1,
        title: 'Champ magnétique et loi de Biot et Savart',
        summary: 'Le champ magnétique, la loi de Biot et Savart, le fil infini, la spire circulaire, le solénoïde et les symétries des courants.',
        conceptExplanation: r`Un courant électrique crée un **champ magnétique** $\vec{B}$ (en teslas, T). Chaque élément de courant $I\,d\vec{\ell}$ apporte une contribution donnée par la **loi de Biot et Savart** ; on additionne (intègre) pour obtenir le champ des circuits usuels : fil rectiligne, spire, solénoïde. Ordres de grandeur : champ terrestre $\approx 5\times10^{-5}\text{ T}$, aimant courant $\approx 0{,}1\text{ T}$.`,
        formulas: [
          { name: 'Loi de Biot et Savart', formula: r`d\vec{B} = \frac{\mu_0}{4\pi}\,\frac{I\,d\vec{\ell}\wedge\vec{u}}{r^2}`, note: r`$\mu_0 = 4\pi\times10^{-7}\text{ H/m}$` },
          { name: 'Fil infini', formula: r`B = \frac{\mu_0 I}{2\pi d}` },
          { name: 'Spire (centre) et solénoïde', formula: r`B_{\text{centre}} = \frac{\mu_0 I}{2R} \quad ; \quad B_{\text{sol}} = \mu_0\,n\,I` },
        ],
        keyRule: r`Le champ magnétique est perpendiculaire aux plans de symétrie des courants et contenu dans leurs plans d’antisymétrie : l’inverse du champ électrique.`,
        workedExample: {
          title: 'Champ au centre d’un solénoïde',
          statement: r`Un solénoïde de longueur $L = 0{,}5\text{ m}$ comporte $N = 1000$ spires parcourues par $I = 2\text{ A}$. Calcule le champ à l’intérieur ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$).`,
          methodSteps: [
            r`Nombre de spires par mètre : $n = \frac{N}{L} = \frac{1000}{0{,}5} = 2000\text{ m}^{-1}$.`,
            r`$B = \mu_0 n I = 4\pi\times10^{-7}\times2000\times2 \approx 5{,}03\times10^{-3}\text{ T}$.`,
          ],
          conclusion: r`$B \approx 5\text{ mT}$, uniforme et parallèle à l’axe à l’intérieur du solénoïde.`,
        },
        visualSchema: { type: 'custom_svg', title: 'Lignes du champ magnétique d’un fil', svgContent: SVG_FIL_B },
        structuredSteps: [
          step(1, 'definition', 'Champ B', 'Le champ magnétique',
            r`Un aimant ou un courant crée un champ magnétique $\vec{B}$, mesuré en **teslas** ($\text{T}$). On le visualise avec la limaille de fer ou une boussole, qui s’oriente selon $\vec{B}$. Les sources de $\vec{B}$ sont les **charges en mouvement** (courants), alors que les sources de $\vec{E}$ sont les charges, même immobiles.`,
            qcm('lmd_srit_l1_estat_ch4_p1_ex1',
              'Quelle est la source d’un champ magnétique en magnétostatique ?',
              ['Des charges immobiles', 'Des courants électriques (charges en mouvement)', 'Uniquement les aimants naturels', 'Une différence de potentiel sans courant'],
              1, 'Le champ magnétique est créé par des charges en mouvement, c’est-à-dire des courants (même les aimants s’expliquent par des courants à l’échelle atomique). Les charges immobiles ne créent qu’un champ électrique.',
              'Pense à l’expérience d’Œrsted : un fil parcouru par un courant fait dévier une boussole.')),
          step(2, 'propriete', 'Biot et Savart', 'La loi de Biot et Savart',
            r`Un élément de circuit $I\,d\vec{\ell}$ crée en $M$ le champ $d\vec{B} = \frac{\mu_0}{4\pi}\frac{I\,d\vec{\ell}\wedge\vec{u}}{r^2}$, où $\vec{u}$ va de l’élément vers $M$. Le produit vectoriel impose que $d\vec{B}$ soit **perpendiculaire** à la fois au courant et à la direction de $M$ : les lignes de champ tournent autour du courant (règle de la main droite).`,
            qcm('lmd_srit_l1_estat_ch4_p1_ex2',
              r`D’après la loi de Biot et Savart $d\vec{B} = \frac{\mu_0}{4\pi}\frac{I\,d\vec{\ell}\wedge\vec{u}}{r^2}$, comment est orienté le champ $d\vec{B}$ créé par un élément de courant ?`,
              ['Parallèle à l’élément de courant', 'Dirigé de l’élément vers le point M', 'Perpendiculaire au plan formé par l’élément de courant et le vecteur u', 'Dirigé du point M vers l’élément'],
              2, r`Le produit vectoriel $d\vec{\ell}\wedge\vec{u}$ est perpendiculaire à $d\vec{\ell}$ et à $\vec{u}$, donc au plan qu’ils forment : le champ tourne autour du courant.`,
              'Un produit vectoriel est perpendiculaire à ses deux vecteurs.')),
          step(3, 'propriete', 'Fil infini', 'Le champ d’un fil rectiligne infini',
            r`En intégrant Biot et Savart le long d’un fil infini, on obtient $B = \frac{\mu_0 I}{2\pi d}$ à la distance $d$ du fil. Les lignes de champ sont des **cercles** centrés sur le fil, orientés par la règle de la main droite (pouce dans le sens du courant).`,
            qcm('lmd_srit_l1_estat_ch4_p1_ex3',
              r`Un fil rectiligne infini est parcouru par un courant $I = 10\text{ A}$. Quel est le champ magnétique à $d = 5\text{ cm}$ du fil ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$, $B = \frac{\mu_0 I}{2\pi d}$) ?`,
              [r`$4\,\mu\text{T}$`, r`$400\,\mu\text{T}$`, r`$40\,\mu\text{T}$`, r`$0{,}4\text{ T}$`],
              2, r`$B = \frac{\mu_0 I}{2\pi d} = \frac{2\times10^{-7}\times10}{0{,}05} = 4\times10^{-5}\text{ T} = 40\,\mu\text{T}$ (proche du champ terrestre).`,
              r`$\frac{\mu_0}{2\pi} = 2\times10^{-7}$.`)),
          step(4, 'propriete', 'Spire', 'Le champ d’une spire circulaire',
            r`Au **centre** d’une spire de rayon $R$ parcourue par $I$ : $B = \frac{\mu_0 I}{2R}$. Sur l’axe, à la distance $x$ du centre : $B(x) = \frac{\mu_0 I R^2}{2(R^2+x^2)^{3/2}}$. Le champ est porté par l’axe ; sa face « nord » est celle d’où sortent les lignes de champ.`,
            qcm('lmd_srit_l1_estat_ch4_p1_ex4',
              r`Une spire circulaire de rayon $R = 0{,}1\text{ m}$ est parcourue par $I = 2\text{ A}$ ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$). Quel est le champ magnétique en son centre, sachant que $B = \frac{\mu_0 I}{2R}$ ?`,
              [r`$12{,}6\,\mu\text{T}$`, r`$4\,\mu\text{T}$`, r`$1{,}26\,\mu\text{T}$`, r`$126\,\mu\text{T}$`],
              0, r`$B = \frac{4\pi\times10^{-7}\times2}{0{,}2} = 4\pi\times10^{-6} \approx 1{,}26\times10^{-5}\text{ T} = 12{,}6\,\mu\text{T}$.`,
              r`$2R = 0{,}2\text{ m}$.`)),
          step(5, 'methode', 'Solénoïde', 'Le champ dans un solénoïde',
            r`Un solénoïde long (longueur grande devant son rayon) crée à l’intérieur un champ **uniforme**, parallèle à l’axe : $B = \mu_0 n I$, où $n = \frac{N}{L}$ est le nombre de spires par mètre. À l’extérieur d’un solénoïde idéal, le champ est nul.`,
            qcm('lmd_srit_l1_estat_ch4_p1_ex5',
              r`Un solénoïde de longueur $L = 0{,}5\text{ m}$ comporte $N = 1000$ spires parcourues par $I = 2\text{ A}$ ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$). Quel est le champ à l’intérieur ?`,
              [r`$2{,}5\text{ mT}$`, r`$5{,}0\text{ mT}$`, r`$0{,}5\text{ mT}$`, r`$10\text{ mT}$`],
              1, r`$n = \frac{1000}{0{,}5} = 2000\text{ m}^{-1}$ et $B = \mu_0 nI = 4\pi\times10^{-7}\times2000\times2 \approx 5{,}03\times10^{-3}\text{ T} \approx 5{,}0\text{ mT}$.`,
              r`Calcule d’abord $n = N/L$.`),
            { formula: { name: 'Solénoïde long', formula: r`B = \mu_0\,\frac{N}{L}\,I` } }),
          step(6, 'piege', 'Symétries', 'Les symétries de B sont inversées',
            r`Piège : $\vec{B}$ est un **pseudo-vecteur**. Ses règles de symétrie sont l’inverse de celles de $\vec{E}$ : en un point d’un **plan de symétrie** des courants, $\vec{B}$ est **perpendiculaire** au plan ; en un point d’un **plan d’antisymétrie**, $\vec{B}$ est **contenu** dans le plan. Exemple : pour un fil, tout plan contenant le fil est un plan de symétrie, donc $\vec{B}$ est orthoradial.`,
            qcm('lmd_srit_l1_estat_ch4_p1_ex6',
              'Un point M appartient à un plan de SYMÉTRIE d’une distribution de courants. Comment est orienté le champ magnétique en M ?',
              ['Contenu dans le plan', 'Perpendiculaire au plan', 'Nul obligatoirement', 'Parallèle aux courants'],
              1, 'Pour le champ magnétique (pseudo-vecteur), un plan de symétrie des courants impose un champ perpendiculaire au plan, contrairement au champ électrique qui y serait contenu.',
              'Pense au fil infini : le plan contenant le fil est de symétrie et B tourne autour.')),
        ],
      }),
      makePoint({
        id: 'lmd_srit_l1_estat_ch4_p2',
        order: 2,
        title: 'Flux magnétique et théorème d’Ampère',
        summary: 'Conservation du flux du champ magnétique, théorème d’Ampère, courant enlacé, fil épais, tore et solénoïde, lignes et tubes de champ.',
        conceptExplanation: r`Le flux de $\vec{B}$ à travers toute surface fermée est **nul** : il n’existe pas de charge magnétique isolée, les lignes de champ sont fermées. La circulation de $\vec{B}$ le long d’un contour fermé est donnée par le **théorème d’Ampère** : $\oint \vec{B}\cdot d\vec{\ell} = \mu_0 I_{\text{enlacé}}$. Comme Gauss pour $\vec{E}$, il permet de calculer $B$ très vite quand la symétrie est forte.`,
        formulas: [
          { name: 'Conservation du flux', formula: r`\oint_S \vec{B}\cdot d\vec{S} = 0` },
          { name: 'Théorème d’Ampère', formula: r`\oint_C \vec{B}\cdot d\vec{\ell} = \mu_0\,I_{\text{enlacé}}` },
          { name: 'Bobine torique', formula: r`B = \frac{\mu_0 N I}{2\pi r}` },
        ],
        keyRule: 'Le courant enlacé se compte avec son signe : positif s’il traverse la surface dans le sens donné par l’orientation du contour (main droite).',
        workedExample: {
          title: 'Champ à l’intérieur d’un fil épais',
          statement: r`Un fil cylindrique de rayon $R = 2\text{ mm}$ est parcouru par $I = 20\text{ A}$ uniformément réparti. Calcule $B$ à $r = 1\text{ mm}$ de l’axe ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$).`,
          methodSteps: [
            r`Contour d’Ampère : cercle de rayon $r$ centré sur l’axe. Circulation : $B\times2\pi r$.`,
            r`Courant enlacé : $I\frac{\pi r^2}{\pi R^2} = I\frac{r^2}{R^2}$.`,
            r`Donc $B = \frac{\mu_0 I r}{2\pi R^2} = \frac{2\times10^{-7}\times20\times10^{-3}}{4\times10^{-6}} = 10^{-3}\text{ T}$.`,
          ],
          conclusion: r`$B = 1\text{ mT}$ ; à l’intérieur du fil, $B$ croît proportionnellement à $r$.`,
        },
        structuredSteps: [
          step(1, 'propriete', 'Flux conservatif', 'Le flux de B à travers une surface fermée est nul',
            r`Pour toute surface fermée, $\oint \vec{B}\cdot d\vec{S} = 0$ : autant de lignes de champ entrent que de lignes sortent. Il n’existe pas de « charge magnétique » isolée (monopôle) ; si l’on coupe un aimant en deux, on obtient deux aimants avec chacun un pôle nord et un pôle sud.`,
            qcm('lmd_srit_l1_estat_ch4_p2_ex1',
              r`On entoure le pôle nord d’un aimant droit par une surface fermée ; le flux du champ magnétique sortant par une partie de la surface vaut $+3\times10^{-4}\text{ Wb}$. Que vaut le flux total à travers la surface fermée ?`,
              [r`$0\text{ Wb}$`, r`$+3\times10^{-4}\text{ Wb}$`, r`$-3\times10^{-4}\text{ Wb}$`, r`$+6\times10^{-4}\text{ Wb}$`],
              0, r`Le flux de $\vec{B}$ à travers toute surface fermée est nul : le flux sortant est exactement compensé par un flux entrant ailleurs (les lignes de champ sont fermées).`,
              'Il n’existe pas de pôle magnétique isolé.')),
          step(2, 'propriete', 'Ampère', 'Le théorème d’Ampère',
            r`La circulation de $\vec{B}$ sur un contour fermé orienté vaut $\mu_0$ fois le **courant enlacé** : $\oint \vec{B}\cdot d\vec{\ell} = \mu_0 I_{\text{enlacé}}$. Chaque courant qui traverse une surface s’appuyant sur le contour compte avec son signe (sens donné par la main droite) ; les courants qui ne traversent pas la surface ne comptent pas.`,
            qcm('lmd_srit_l1_estat_ch4_p2_ex2',
              r`Un contour fermé orienté enlace un courant de $5\text{ A}$ dans le sens positif et un courant de $3\text{ A}$ dans le sens opposé ; un courant de $2\text{ A}$ passe à l’extérieur du contour ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$). Que vaut la circulation de $\vec{B}$ ?`,
              [r`$\mu_0\times10$`, r`$\mu_0\times4 \approx 5{,}0\times10^{-6}\text{ T}\cdot\text{m}$`, r`$\mu_0\times8$`, r`$\mu_0\times2 \approx 2{,}5\times10^{-6}\text{ T}\cdot\text{m}$`],
              3, r`$I_{\text{enlacé}} = 5 - 3 = 2\text{ A}$ (le courant extérieur ne compte pas). Circulation $= \mu_0\times2 = 8\pi\times10^{-7} \approx 2{,}5\times10^{-6}\text{ T}\cdot\text{m}$.`,
              'Compte les courants avec leur signe, et seulement ceux qui traversent le contour.'),
            { formula: { name: 'Théorème d’Ampère', formula: r`\oint \vec{B}\cdot d\vec{\ell} = \mu_0\,I_{\text{enlacé}}` } }),
          step(3, 'methode', 'Fil épais', 'Ampère pour un fil épais',
            r`Pour un fil cylindrique de rayon $R$ parcouru par $I$ uniforme, on prend un cercle de rayon $r$ coaxial. À l’**extérieur** ($r > R$) : $B = \frac{\mu_0 I}{2\pi r}$. À l’**intérieur** ($r < R$), le courant enlacé n’est que $I\frac{r^2}{R^2}$, d’où $B = \frac{\mu_0 I r}{2\pi R^2}$ : le champ croît linéairement jusqu’à la surface.`,
            qcm('lmd_srit_l1_estat_ch4_p2_ex3',
              r`Un fil cylindrique de rayon $R = 2\text{ mm}$ est parcouru par $I = 20\text{ A}$ uniformément réparti ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$). Quel est le champ à $r = 1\text{ mm}$ de l’axe, sachant que $B = \frac{\mu_0 I r}{2\pi R^2}$ à l’intérieur ?`,
              [r`$2\text{ mT}$`, r`$4\text{ mT}$`, r`$1\text{ mT}$`, r`$0{,}5\text{ mT}$`],
              2, r`$B = \frac{\mu_0 I r}{2\pi R^2} = \frac{2\times10^{-7}\times20\times10^{-3}}{(2\times10^{-3})^2} = \frac{4\times10^{-9}}{4\times10^{-6}} = 10^{-3}\text{ T} = 1\text{ mT}$.`,
              r`$\frac{\mu_0}{2\pi} = 2\times10^{-7}$ et $R^2 = 4\times10^{-6}\text{ m}^2$.`)),
          step(4, 'exemple', 'Tore', 'La bobine torique',
            r`Une bobine **torique** est un solénoïde refermé sur lui-même. Un cercle de rayon $r$ à l’intérieur du tore enlace $N$ fois le courant : $B\times2\pi r = \mu_0 N I$, d’où $B = \frac{\mu_0 N I}{2\pi r}$. À l’extérieur du tore, le courant enlacé total est nul : $B = 0$ (le champ est confiné, utile pour les transformateurs).`,
            qcm('lmd_srit_l1_estat_ch4_p2_ex4',
              r`Une bobine torique de $N = 500$ spires est parcourue par $I = 1\text{ A}$ ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$). Quel est le champ à l’intérieur, à $r = 0{,}1\text{ m}$ de l’axe du tore, avec $B = \frac{\mu_0 NI}{2\pi r}$ ?`,
              [r`$1\text{ mT}$`, r`$10\text{ mT}$`, r`$0{,}1\text{ mT}$`, r`$6{,}3\text{ mT}$`],
              0, r`$B = \frac{2\times10^{-7}\times500\times1}{0{,}1} = 10^{-3}\text{ T} = 1\text{ mT}$.`,
              r`$\frac{\mu_0}{2\pi} = 2\times10^{-7}$.`)),
          step(5, 'definition', 'Lignes et tubes', 'Lignes et tubes de champ magnétique',
            r`Les lignes de champ magnétique sont tangentes à $\vec{B}$ et **toujours fermées** (autour d’un fil, à travers une spire, de part et d’autre d’un aimant). Un **tube de champ** est l’ensemble des lignes s’appuyant sur un contour fermé : comme le flux est conservatif, le flux est le même à travers toutes les sections d’un tube.`,
            qcm('lmd_srit_l1_estat_ch4_p2_ex5',
              r`Un tube de champ magnétique a une section $S_1 = 2\text{ cm}^2$ où le champ vaut $B_1 = 0{,}5\text{ T}$ (uniforme et perpendiculaire). Plus loin, sa section vaut $S_2 = 5\text{ cm}^2$. Que vaut le champ $B_2$ dans cette section ?`,
              [r`$1{,}25\text{ T}$`, r`$0{,}5\text{ T}$`, r`$0{,}1\text{ T}$`, r`$0{,}2\text{ T}$`],
              3, r`Le flux est conservé le long du tube : $B_1S_1 = B_2S_2$, donc $B_2 = \frac{0{,}5\times2}{5} = 0{,}2\text{ T}$. Le champ diminue quand le tube s’élargit.`,
              'Le flux est le même à travers chaque section du tube.')),
          step(6, 'piege', 'Validité', 'Ampère toujours vrai, mais pas toujours utile',
            r`Piège : le théorème d’Ampère est toujours vrai en régime permanent, mais il ne donne $B$ que si la symétrie rend $B$ **constant** et **tangent** sur le contour choisi. Pour une spire circulaire, aucun contour simple ne convient : on revient à Biot et Savart. Autre piège : dans un solénoïde idéal, le champ extérieur est nul.`,
            qcm('lmd_srit_l1_estat_ch4_p2_ex6',
              'Pour calculer le champ magnétique au centre d’UNE spire circulaire parcourue par un courant I, quelle méthode faut-il utiliser ?',
              ['Le théorème d’Ampère sur un cercle de même rayon', 'La loi de Biot et Savart', 'Le théorème de Gauss', 'La conservation du flux'],
              1, r`Une seule spire n’a pas une symétrie suffisante : sur aucun contour simple le champ n’est constant et tangent. On intègre Biot et Savart, ce qui donne $B = \frac{\mu_0 I}{2R}$.`,
              'Ampère n’aide que si B est constant et tangent au contour.')),
        ],
      }),
      makePoint({
        id: 'lmd_srit_l1_estat_ch4_p3',
        order: 3,
        title: 'Forces de Laplace et interaction entre courants',
        summary: 'Force de Laplace sur un conducteur, règle de la main droite, interaction entre deux fils parallèles, couple sur une spire et travail des forces magnétiques.',
        conceptExplanation: r`Un conducteur parcouru par un courant et placé dans un champ magnétique subit la **force de Laplace** $d\vec{F} = I\,d\vec{\ell}\wedge\vec{B}$. C’est le principe des moteurs électriques et des haut-parleurs. Deux fils parcourus par des courants agissent l’un sur l’autre ; une spire subit un **couple** qui l’oriente dans le champ.`,
        formulas: [
          { name: 'Force de Laplace', formula: r`\vec{F} = I\,\vec{L}\wedge\vec{B} \quad ; \quad F = I L B\sin\alpha` },
          { name: 'Deux fils parallèles', formula: r`\frac{F}{L} = \frac{\mu_0\,I_1 I_2}{2\pi d}` },
          { name: 'Couple sur une spire', formula: r`\vec{\Gamma} = \vec{m}\wedge\vec{B} \quad ; \quad m = N I S` },
        ],
        keyRule: 'Deux fils parallèles s’attirent si leurs courants sont de même sens et se repoussent s’ils sont de sens contraires.',
        workedExample: {
          title: 'Force entre deux câbles parallèles',
          statement: r`Deux câbles parallèles distants de $d = 0{,}1\text{ m}$ sont parcourus chacun par $10\text{ A}$ dans le même sens. Calcule la force par mètre de câble ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$).`,
          methodSteps: [
            r`Le câble 1 crée au niveau du câble 2 le champ $B_1 = \frac{\mu_0 I_1}{2\pi d}$.`,
            r`La force de Laplace par mètre sur le câble 2 vaut $\frac{F}{L} = I_2 B_1 = \frac{\mu_0 I_1 I_2}{2\pi d} = \frac{2\times10^{-7}\times100}{0{,}1} = 2\times10^{-4}\text{ N/m}$.`,
            r`Courants de même sens : la force est attractive.`,
          ],
          conclusion: r`$2\times10^{-4}\text{ N}$ par mètre, attractive.`,
        },
        visualSchema: { type: 'custom_svg', title: 'Deux fils parallèles parcourus par des courants', svgContent: SVG_DEUX_FILS },
        structuredSteps: [
          step(1, 'propriete', 'Laplace', 'La force de Laplace',
            r`Une portion de conducteur rectiligne de longueur $L$, parcourue par $I$ et placée dans un champ uniforme $\vec{B}$, subit $\vec{F} = I\,\vec{L}\wedge\vec{B}$, de norme $F = ILB\sin\alpha$ où $\alpha$ est l’angle entre le conducteur et le champ. La force est maximale quand le conducteur est perpendiculaire au champ.`,
            qcm('lmd_srit_l1_estat_ch4_p3_ex1',
              r`Une tige de longueur $L = 0{,}2\text{ m}$ parcourue par $I = 5\text{ A}$ est placée perpendiculairement à un champ magnétique uniforme $B = 0{,}4\text{ T}$. Quelle est la force de Laplace ?`,
              [r`$0{,}04\text{ N}$`, r`$4\text{ N}$`, r`$0{,}4\text{ N}$`, r`$0{,}1\text{ N}$`],
              2, r`$F = ILB\sin90° = 5\times0{,}2\times0{,}4\times1 = 0{,}4\text{ N}$.`,
              'Perpendiculaire : sin α = 1.'),
            { formula: { name: 'Force de Laplace', formula: r`F = I\,L\,B\,\sin\alpha` } }),
          step(2, 'methode', 'Orientation', 'Trouver le sens de la force',
            r`Le sens de $\vec{F} = I\vec{L}\wedge\vec{B}$ se trouve avec la règle de la main droite (ou des trois doigts) : pouce = sens du courant, index = $\vec{B}$, majeur = $\vec{F}$. En pratique : si le courant va vers $+\vec{u}_x$ et $\vec{B}$ vers $+\vec{u}_y$, la force va vers $+\vec{u}_z$ car $\vec{u}_x\wedge\vec{u}_y = \vec{u}_z$.`,
            qcm('lmd_srit_l1_estat_ch4_p3_ex2',
              r`Dans un repère direct, un conducteur est parcouru par un courant dirigé selon $+\vec{u}_x$ et placé dans un champ magnétique dirigé selon $+\vec{u}_y$. Quelle est la direction de la force de Laplace $\vec{F} = I\vec{L}\wedge\vec{B}$ ?`,
              [r`$+\vec{u}_z$`, r`$-\vec{u}_z$`, r`$+\vec{u}_y$`, r`$-\vec{u}_x$`],
              0, r`$\vec{u}_x\wedge\vec{u}_y = \vec{u}_z$ dans un repère direct : la force est dirigée selon $+\vec{u}_z$.`,
              r`Rappelle-toi $\vec{u}_x\wedge\vec{u}_y = \vec{u}_z$.`)),
          step(3, 'propriete', 'Deux fils', 'Interaction entre deux fils parallèles',
            r`Chaque fil est placé dans le champ de l’autre : la force par mètre vaut $\frac{F}{L} = \frac{\mu_0 I_1 I_2}{2\pi d}$. Courants de **même sens** : **attraction** ; courants de **sens contraires** : **répulsion**. C’est l’inverse de ce qui se passe pour des charges électriques de même signe.`,
            qcm('lmd_srit_l1_estat_ch4_p3_ex3',
              r`Deux fils parallèles distants de $d = 0{,}1\text{ m}$ sont parcourus chacun par $10\text{ A}$ dans le même sens ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$). Quelle est la force par mètre de fil ?`,
              [r`$2\times10^{-4}\text{ N/m}$, répulsive`, r`$2\times10^{-5}\text{ N/m}$, attractive`, r`$2\times10^{-3}\text{ N/m}$, attractive`, r`$2\times10^{-4}\text{ N/m}$, attractive`],
              3, r`$\frac{F}{L} = \frac{\mu_0 I_1I_2}{2\pi d} = \frac{2\times10^{-7}\times10\times10}{0{,}1} = 2\times10^{-4}\text{ N/m}$. Courants de même sens : les fils s’attirent.`,
              'Même sens de courant : attraction.')),
          step(4, 'exemple', 'Ampère (unité)', 'L’ancienne définition de l’ampère',
            r`Jusqu’en 2019, l’ampère était défini par cette interaction : deux fils parallèles infinis distants de $1\text{ m}$, parcourus par $1\text{ A}$, s’attirent avec une force de $2\times10^{-7}\text{ N}$ par mètre. C’est pourquoi $\mu_0$ valait exactement $4\pi\times10^{-7}\text{ H/m}$.`,
            qcm('lmd_srit_l1_estat_ch4_p3_ex4',
              r`Deux fils parallèles infinis distants de $d = 1\text{ m}$ sont parcourus chacun par $1\text{ A}$ ($\mu_0 = 4\pi\times10^{-7}\text{ H/m}$, $\frac{F}{L} = \frac{\mu_0 I_1I_2}{2\pi d}$). Quelle force s’exerce par mètre de fil ?`,
              [r`$4\pi\times10^{-7}\text{ N/m}$`, r`$10^{-7}\text{ N/m}$`, r`$2\times10^{-7}\text{ N/m}$`, r`$1\text{ N/m}$`],
              2, r`$\frac{F}{L} = \frac{4\pi\times10^{-7}\times1\times1}{2\pi\times1} = 2\times10^{-7}\text{ N/m}$ : c’est l’ancienne définition de l’ampère.`,
              r`$\frac{4\pi}{2\pi} = 2$.`)),
          step(5, 'methode', 'Couple', 'Le couple sur une spire (moteur)',
            r`Un cadre de $N$ spires de surface $S$ parcouru par $I$ a un **moment magnétique** $\vec{m} = NIS\,\vec{n}$. Dans un champ uniforme, il subit le couple $\vec{\Gamma} = \vec{m}\wedge\vec{B}$, de norme $NISB\sin\theta$ : il tourne pour aligner $\vec{m}$ sur $\vec{B}$. C’est le principe du moteur électrique et du galvanomètre.`,
            qcm('lmd_srit_l1_estat_ch4_p3_ex5',
              r`Un cadre de $N = 100$ spires, de surface $S = 4\times10^{-4}\text{ m}^2$, parcouru par $I = 0{,}5\text{ A}$, est placé dans un champ $B = 0{,}2\text{ T}$ parallèle au plan du cadre ($\theta = 90°$ entre $\vec{m}$ et $\vec{B}$). Quel est le couple subi ?`,
              [r`$4\times10^{-3}\text{ N}\cdot\text{m}$`, r`$4\times10^{-5}\text{ N}\cdot\text{m}$`, r`$0\text{ N}\cdot\text{m}$`, r`$0{,}4\text{ N}\cdot\text{m}$`],
              0, r`$\Gamma = NISB\sin\theta = 100\times0{,}5\times4\times10^{-4}\times0{,}2\times1 = 4\times10^{-3}\text{ N}\cdot\text{m}$ (valeur maximale).`,
              r`Multiplie les cinq facteurs ; $\sin 90° = 1$.`)),
          step(6, 'piege', 'Travail', 'Le travail des forces de Laplace',
            r`Lors d’un déplacement à courant constant, le travail des forces de Laplace vaut $W = I\,\Delta\Phi$ (théorème de Maxwell), où $\Delta\Phi$ est la variation du flux coupé ou traversant le circuit. Piège : la force de Laplace **travaille** (elle fait tourner les moteurs), alors que la force magnétique sur une charge isolée ne travaille jamais.`,
            qcm('lmd_srit_l1_estat_ch4_p3_ex6',
              r`Un circuit parcouru par un courant constant $I = 2\text{ A}$ se déplace dans un champ magnétique ; le flux qui le traverse augmente de $\Delta\Phi = 0{,}03\text{ Wb}$. Quel est le travail des forces de Laplace ?`,
              [r`$0{,}015\text{ J}$`, r`$0{,}06\text{ J}$`, r`$0\text{ J}$`, r`$0{,}6\text{ J}$`],
              1, r`Théorème de Maxwell : $W = I\,\Delta\Phi = 2\times0{,}03 = 0{,}06\text{ J}$.`,
              r`$W = I\,\Delta\Phi$.`)),
        ],
      }),
    ],
  },

  // ==========================================================================
  // CHAPITRE 5 : MOUVEMENT DES PARTICULES CHARGÉES
  // ==========================================================================
  {
    id: 'lmd_srit_l1_estat_ch5',
    subjectId: 'lmd_electrostatique',
    gradeLevel: 'lmd_srit_l1',
    semesters: [1],
    order: 5,
    officialVolumeHours: 8,
    contentVersion: 2,
    source: SOURCE,
    title: 'Mouvement des particules chargées',
    summary: 'Force de Lorentz, accélération et déviation dans un champ électrique uniforme, mouvement circulaire dans un champ magnétique uniforme, applications (Thomson, spectrographe, effet Hall).',
    points: [
      makePoint({
        id: 'lmd_srit_l1_estat_ch5_p1',
        order: 1,
        title: 'Force de Lorentz et mouvement dans un champ électrique uniforme',
        summary: 'Force de Lorentz, accélération d’une particule, vitesse acquise sous une tension, déviation parabolique entre deux plaques.',
        conceptExplanation: r`Une particule de charge $q$ et de vitesse $\vec{v}$ subit la **force de Lorentz** $\vec{F} = q(\vec{E} + \vec{v}\wedge\vec{B})$. Le poids est en général négligeable devant cette force. Dans un champ électrique **uniforme**, l’accélération $\vec{a} = \frac{q\vec{E}}{m}$ est constante : la particule est accélérée (canon à électrons) ou déviée selon une **parabole** (oscilloscope, imprimante à jet d’encre).`,
        formulas: [
          { name: 'Force de Lorentz', formula: r`\vec{F} = q\left(\vec{E} + \vec{v}\wedge\vec{B}\right)` },
          { name: 'Vitesse acquise sous une tension U (départ au repos)', formula: r`\frac{1}{2}mv^2 = |q|\,U` },
          { name: 'Trajectoire entre deux plaques', formula: r`y = \frac{qE}{2mv_0^2}\,x^2` },
        ],
        keyRule: 'La partie magnétique q v∧B est perpendiculaire à la vitesse : elle ne travaille jamais et ne change pas la valeur de la vitesse.',
        workedExample: {
          title: 'Vitesse d’un électron accéléré sous 100 V',
          statement: r`Un électron ($m = 9{,}1\times10^{-31}\text{ kg}$, $|q| = 1{,}6\times10^{-19}\text{ C}$) part du repos et est accéléré sous $U = 100\text{ V}$. Calcule sa vitesse finale.`,
          methodSteps: [
            r`Théorème de l’énergie cinétique : $\frac{1}{2}mv^2 = |q|U = 1{,}6\times10^{-17}\text{ J}$.`,
            r`$v^2 = \frac{2\times1{,}6\times10^{-17}}{9{,}1\times10^{-31}} \approx 3{,}52\times10^{13}\text{ m}^2/\text{s}^2$.`,
            r`$v \approx 5{,}9\times10^{6}\text{ m/s}$ (2 % de la vitesse de la lumière : mécanique classique valable).`,
          ],
          conclusion: r`$v \approx 5{,}9\times10^{6}\text{ m/s}$.`,
        },
        visualSchema: { type: 'custom_svg', title: 'Déviation d’un électron entre deux plaques', svgContent: SVG_DEVIATION },
        structuredSteps: [
          step(1, 'definition', 'Lorentz', 'La force de Lorentz',
            r`Une charge $q$ de vitesse $\vec{v}$ dans des champs $\vec{E}$ et $\vec{B}$ subit $\vec{F} = q\vec{E} + q\vec{v}\wedge\vec{B}$. La partie électrique peut accélérer ou freiner la particule. La partie magnétique est toujours **perpendiculaire à la vitesse** : sa puissance $\vec{F}\cdot\vec{v}$ est nulle, elle ne fait que courber la trajectoire.`,
            qcm('lmd_srit_l1_estat_ch5_p1_ex1',
              r`Un proton se déplace dans un champ magnétique uniforme seul ($\vec{E} = \vec{0}$). Que peut-on dire de l’énergie cinétique du proton ?`,
              ['Elle augmente toujours', 'Elle diminue toujours', 'Elle reste constante', 'Elle dépend du signe de la charge'],
              2, r`La force magnétique $q\vec{v}\wedge\vec{B}$ est perpendiculaire à la vitesse : sa puissance est nulle, donc l’énergie cinétique (et la valeur de la vitesse) reste constante.`,
              r`Calcule la puissance $\vec{F}\cdot\vec{v}$ de la force magnétique.`)),
          step(2, 'methode', 'Accélération', 'Accélération dans un champ électrique uniforme',
            r`D’après la deuxième loi de Newton, $m\vec{a} = q\vec{E}$ (poids négligé), donc $a = \frac{|q|E}{m}$, constante. Pour un électron, la masse étant minuscule ($9{,}1\times10^{-31}\text{ kg}$), l’accélération est gigantesque même dans un champ modeste.`,
            qcm('lmd_srit_l1_estat_ch5_p1_ex2',
              r`Un électron ($|q| = 1{,}6\times10^{-19}\text{ C}$, $m = 9{,}1\times10^{-31}\text{ kg}$) est placé dans un champ électrique uniforme $E = 1000\text{ V/m}$. Quelle est la valeur de son accélération ?`,
              [r`$1{,}76\times10^{11}\text{ m/s}^2$`, r`$1{,}76\times10^{14}\text{ m/s}^2$`, r`$1{,}6\times10^{-16}\text{ m/s}^2$`, r`$9{,}8\text{ m/s}^2$`],
              1, r`$a = \frac{|q|E}{m} = \frac{1{,}6\times10^{-19}\times10^{3}}{9{,}1\times10^{-31}} \approx 1{,}76\times10^{14}\text{ m/s}^2$.`,
              r`$\frac{1{,}6}{9{,}1} \approx 0{,}176$.`)),
          step(3, 'methode', 'Tension accélératrice', 'Vitesse acquise sous une tension',
            r`Une particule partant du repos et accélérée sous une tension $U$ reçoit le travail $|q|U$ : $\frac{1}{2}mv^2 = |q|U$, donc $v = \sqrt{\frac{2|q|U}{m}}$. C’est le principe du canon à électrons des anciens téléviseurs et des microscopes électroniques.`,
            qcm('lmd_srit_l1_estat_ch5_p1_ex3',
              r`Un électron ($|q| = 1{,}6\times10^{-19}\text{ C}$, $m = 9{,}1\times10^{-31}\text{ kg}$) part du repos et est accéléré sous $U = 100\text{ V}$. Quelle est sa vitesse finale ?`,
              [r`$5{,}9\times10^{4}\text{ m/s}$`, r`$3{,}5\times10^{13}\text{ m/s}$`, r`$1{,}9\times10^{6}\text{ m/s}$`, r`$5{,}9\times10^{6}\text{ m/s}$`],
              3, r`$v = \sqrt{\frac{2\times1{,}6\times10^{-19}\times100}{9{,}1\times10^{-31}}} = \sqrt{3{,}52\times10^{13}} \approx 5{,}9\times10^{6}\text{ m/s}$.`,
              'N’oublie pas la racine carrée à la fin.'),
            { formula: { name: 'Vitesse acquise', formula: r`v = \sqrt{\frac{2|q|U}{m}}` } }),
          step(4, 'propriete', 'Déviation', 'Trajectoire parabolique entre deux plaques',
            r`Un électron entre avec la vitesse $\vec{v}_0$ horizontale entre deux plaques où règne un champ vertical uniforme. Horizontalement, rien ne le freine : $x = v_0 t$. Verticalement, il accélère : $y = \frac{1}{2}at^2$. En éliminant $t$ : $y = \frac{|q|E}{2mv_0^2}x^2$, une **parabole**. À la sortie des plaques (longueur $\ell$), la déviation vaut $\frac{|q|E\ell^2}{2mv_0^2}$.`,
            qcm('lmd_srit_l1_estat_ch5_p1_ex4',
              r`Entre deux plaques de longueur $\ell$, la déviation d’un électron à la sortie vaut $Y = \frac{|q|E\ell^2}{2mv_0^2}$. Si l’on double la longueur $\ell$ des plaques (même champ, même vitesse d’entrée), par combien la déviation est-elle multipliée ?`,
              ['Par 2', 'Par √2', 'Par 4', 'Elle ne change pas'],
              2, r`La déviation est proportionnelle à $\ell^2$ : avec $2\ell$, elle est multipliée par $2^2 = 4$.`,
              r`Regarde la puissance de $\ell$ dans la formule.`)),
          step(5, 'exemple', 'Électronvolt', 'L’électronvolt, unité d’énergie des particules',
            r`Une particule de charge $e$ accélérée sous $1\text{ V}$ gagne $1\text{ eV} = 1{,}6\times10^{-19}\text{ J}$. Sous $U$ volts, une particule de charge $e$ gagne donc $U$ électronvolts, et une particule de charge $2e$ (noyau d’hélium) en gagne $2U$. Cette unité évite de manipuler des puissances de 10 négatives.`,
            qcm('lmd_srit_l1_estat_ch5_p1_ex5',
              r`Un proton (charge $+e$) part du repos et est accéléré sous une tension $U = 2000\text{ V}$. Quelle énergie cinétique gagne-t-il ?`,
              [r`$2\text{ keV}$, soit $3{,}2\times10^{-16}\text{ J}$`, r`$2\text{ eV}$`, r`$4\text{ keV}$`, r`$2000\text{ J}$`],
              0, r`$E_c = eU = 2000\text{ eV} = 2\text{ keV}$, soit $2000\times1{,}6\times10^{-19} = 3{,}2\times10^{-16}\text{ J}$.`,
              'Charge e sous U volts : U électronvolts.')),
          step(6, 'piege', 'Sens de déviation', 'Le signe de la charge décide du sens',
            r`Piège : la force $q\vec{E}$ est dans le sens de $\vec{E}$ pour une charge positive, et dans le sens **opposé** pour une charge négative. Le champ va de la plaque $+$ vers la plaque $-$ : un **électron** est donc dévié vers la plaque **positive**, un proton vers la plaque négative.`,
            qcm('lmd_srit_l1_estat_ch5_p1_ex6',
              'Un électron passe entre deux plaques horizontales : la plaque du haut est reliée au pôle + et celle du bas au pôle −. Vers où l’électron est-il dévié ?',
              ['Vers la plaque du bas (−)', 'Vers la plaque du haut (+)', 'Il n’est pas dévié', 'Il fait demi-tour'],
              1, r`Le champ est dirigé de la plaque $+$ (haut) vers la plaque $-$ (bas). La charge de l’électron étant négative, la force $q\vec{E}$ est dirigée vers le haut : il est attiré par la plaque positive.`,
              'Les charges opposées s’attirent.')),
        ],
      }),
      makePoint({
        id: 'lmd_srit_l1_estat_ch5_p2',
        order: 2,
        title: 'Mouvement dans un champ magnétique uniforme et applications',
        summary: 'Mouvement circulaire uniforme, rayon et période cyclotron, trajectoire hélicoïdale, filtre de vitesse (Thomson), spectrographe de masse et effet Hall.',
        conceptExplanation: r`Une particule chargée qui entre perpendiculairement à un champ magnétique uniforme décrit un **cercle** à vitesse constante : la force magnétique joue le rôle de force centripète. Le rayon $R = \frac{mv}{|q|B}$ dépend de la masse : c’est le principe du **spectrographe de masse**. En combinant $\vec{E}$ et $\vec{B}$ croisés, on sélectionne une vitesse (**expérience de Thomson**) ; dans un conducteur, la déviation des porteurs crée l’**effet Hall** (capteurs de champ).`,
        formulas: [
          { name: 'Rayon de la trajectoire', formula: r`R = \frac{m\,v}{|q|\,B}` },
          { name: 'Période et fréquence cyclotron', formula: r`T = \frac{2\pi m}{|q|B} \quad ; \quad f = \frac{|q|B}{2\pi m}` },
          { name: 'Filtre de vitesse (champs croisés)', formula: r`v = \frac{E}{B}` },
        ],
        keyRule: 'La période du mouvement circulaire ne dépend pas de la vitesse : toutes les particules identiques tournent au même rythme (principe du cyclotron).',
        workedExample: {
          title: 'Rayon de la trajectoire d’un proton',
          statement: r`Un proton ($m = 1{,}67\times10^{-27}\text{ kg}$, $q = 1{,}6\times10^{-19}\text{ C}$) entre à $v = 10^{6}\text{ m/s}$ perpendiculairement à un champ $B = 0{,}1\text{ T}$. Calcule le rayon de sa trajectoire.`,
          methodSteps: [
            r`Force magnétique $qvB$ = force centripète $\frac{mv^2}{R}$, donc $R = \frac{mv}{qB}$.`,
            r`$R = \frac{1{,}67\times10^{-27}\times10^{6}}{1{,}6\times10^{-19}\times0{,}1} = \frac{1{,}67\times10^{-21}}{1{,}6\times10^{-20}} \approx 0{,}104\text{ m}$.`,
          ],
          conclusion: r`$R \approx 10{,}4\text{ cm}$.`,
        },
        visualSchema: { type: 'custom_svg', title: 'Trajectoire circulaire dans un champ magnétique', svgContent: SVG_CERCLE_B },
        structuredSteps: [
          step(1, 'propriete', 'Cercle', 'Un mouvement circulaire uniforme',
            r`Si $\vec{v}_0 \perp \vec{B}$, la force $q\vec{v}\wedge\vec{B}$, perpendiculaire à la vitesse et de norme constante $|q|vB$, est **centripète**. La particule décrit un cercle à vitesse constante, de rayon $R$ tel que $|q|vB = \frac{mv^2}{R}$, soit $R = \frac{mv}{|q|B}$.`,
            qcm('lmd_srit_l1_estat_ch5_p2_ex1',
              r`Un proton ($m = 1{,}67\times10^{-27}\text{ kg}$, $q = 1{,}6\times10^{-19}\text{ C}$) entre à $v = 10^{6}\text{ m/s}$ perpendiculairement à un champ magnétique uniforme $B = 0{,}1\text{ T}$. Quel est le rayon de sa trajectoire ?`,
              [r`$1{,}04\text{ cm}$`, r`$1{,}04\text{ m}$`, r`$10{,}4\text{ cm}$`, r`$0{,}104\text{ mm}$`],
              2, r`$R = \frac{mv}{qB} = \frac{1{,}67\times10^{-27}\times10^{6}}{1{,}6\times10^{-19}\times0{,}1} = \frac{1{,}67\times10^{-21}}{1{,}6\times10^{-20}} \approx 0{,}104\text{ m} = 10{,}4\text{ cm}$.`,
              r`Le dénominateur vaut $1{,}6\times10^{-20}$.`),
            { formula: { name: 'Rayon cyclotron', formula: r`R = \frac{mv}{|q|B}` } }),
          step(2, 'propriete', 'Cyclotron', 'La période ne dépend pas de la vitesse',
            r`Le temps d’un tour vaut $T = \frac{2\pi R}{v} = \frac{2\pi m}{|q|B}$ : la vitesse disparaît ! Une particule plus rapide décrit un cercle plus grand, mais dans le même temps. On en déduit la **fréquence cyclotron** $f = \frac{|q|B}{2\pi m}$, utilisée dans les accélérateurs de particules (cyclotrons).`,
            qcm('lmd_srit_l1_estat_ch5_p2_ex2',
              r`Quelle est la fréquence cyclotron $f = \frac{qB}{2\pi m}$ d’un proton ($q = 1{,}6\times10^{-19}\text{ C}$, $m = 1{,}67\times10^{-27}\text{ kg}$) dans un champ $B = 1\text{ T}$ ?`,
              [r`$15{,}2\text{ MHz}$`, r`$1{,}52\text{ MHz}$`, r`$95{,}8\text{ MHz}$`, r`$152\text{ kHz}$`],
              0, r`$f = \frac{1{,}6\times10^{-19}\times1}{2\pi\times1{,}67\times10^{-27}} = \frac{1{,}6\times10^{-19}}{1{,}049\times10^{-26}} \approx 1{,}52\times10^{7}\text{ Hz} = 15{,}2\text{ MHz}$.`,
              r`$2\pi\times1{,}67\times10^{-27} \approx 1{,}05\times10^{-26}$.`)),
          step(3, 'definition', 'Hélice', 'Vitesse oblique : une hélice',
            r`Si la vitesse n’est pas perpendiculaire au champ, on la décompose : la composante **parallèle** à $\vec{B}$ n’est pas modifiée (mouvement uniforme le long du champ), la composante **perpendiculaire** donne un mouvement circulaire. La combinaison est une **hélice** autour des lignes de champ (aurores polaires).`,
            qcm('lmd_srit_l1_estat_ch5_p2_ex3',
              'Un électron entre dans un champ magnétique uniforme avec une vitesse faisant un angle de 45° avec les lignes de champ. Quelle est sa trajectoire ?',
              ['Une droite', 'Une parabole', 'Un cercle dans un plan perpendiculaire au champ', 'Une hélice d’axe parallèle au champ'],
              3, 'La composante de la vitesse parallèle au champ reste constante (translation le long du champ) et la composante perpendiculaire tourne (cercle) : la combinaison est une hélice.',
              'Décompose la vitesse en une partie parallèle et une partie perpendiculaire au champ.')),
          step(4, 'methode', 'Thomson', 'Le filtre de vitesse (champs croisés)',
            r`Avec un champ $\vec{E}$ et un champ $\vec{B}$ perpendiculaires entre eux et à la vitesse, les forces électrique $qE$ et magnétique $qvB$ sont opposées. Elles se compensent si $v = \frac{E}{B}$ : seules les particules de cette vitesse passent sans être déviées. Thomson s’en est servi pour mesurer le rapport $\frac{e}{m}$ de l’électron.`,
            qcm('lmd_srit_l1_estat_ch5_p2_ex4',
              r`Dans un filtre de vitesse, le champ électrique vaut $E = 2\times10^{4}\text{ V/m}$ et le champ magnétique croisé $B = 0{,}01\text{ T}$. Quelle est la vitesse des particules qui traversent sans être déviées ?`,
              [r`$2\times10^{2}\text{ m/s}$`, r`$2\times10^{6}\text{ m/s}$`, r`$2\times10^{4}\text{ m/s}$`, r`$5\times10^{-7}\text{ m/s}$`],
              1, r`Compensation $qE = qvB$, donc $v = \frac{E}{B} = \frac{2\times10^{4}}{10^{-2}} = 2\times10^{6}\text{ m/s}$ (indépendante de la charge et de la masse).`,
              r`Égale les deux forces : $qE = qvB$.`)),
          step(5, 'exemple', 'Spectrographe', 'Le spectrographe de masse',
            r`Des ions de même charge, sélectionnés à la même vitesse, entrent dans un champ $B$ uniforme : leurs rayons $R = \frac{mv}{qB}$ sont **proportionnels à leur masse**. Ils frappent un détecteur à des endroits différents, ce qui permet de séparer les isotopes (par exemple les isotopes de l’uranium).`,
            qcm('lmd_srit_l1_estat_ch5_p2_ex5',
              r`Deux ions de même charge et de même vitesse entrent dans le même champ magnétique uniforme. L’ion 1 a une masse $m_1 = 20$ u et décrit un cercle de rayon $R_1 = 10\text{ cm}$ ; l’ion 2 a une masse $m_2 = 22$ u. Quel est le rayon $R_2$ ?`,
              [r`$9{,}1\text{ cm}$`, r`$12\text{ cm}$`, r`$10\text{ cm}$`, r`$11\text{ cm}$`],
              3, r`$R = \frac{mv}{qB}$ avec $v$, $q$ et $B$ identiques : $R$ est proportionnel à $m$. $R_2 = R_1\frac{m_2}{m_1} = 10\times\frac{22}{20} = 11\text{ cm}$.`,
              'Le rayon est proportionnel à la masse.')),
          step(6, 'piege', 'Effet Hall', 'L’effet Hall dans un conducteur',
            r`Dans un ruban conducteur d’épaisseur $b$ parcouru par $I$ et placé dans un champ $B$ perpendiculaire, les porteurs de charge sont déviés vers un bord : une tension de Hall apparaît, $U_H = \frac{IB}{nqb}$ ($n$ : densité de porteurs). Piège : le **signe** de $U_H$ dépend du signe des porteurs, c’est ainsi qu’on distingue un semi-conducteur de type N d’un type P.`,
            qcm('lmd_srit_l1_estat_ch5_p2_ex6',
              r`Un ruban de cuivre ($n = 10^{29}\text{ m}^{-3}$, $q = 1{,}6\times10^{-19}\text{ C}$) d’épaisseur $b = 0{,}1\text{ mm}$ est parcouru par $I = 2\text{ A}$ dans un champ $B = 0{,}5\text{ T}$. Quelle est la tension de Hall $U_H = \frac{IB}{nqb}$ ?`,
              [r`$6{,}3\text{ mV}$`, r`$63\,\mu\text{V}$`, r`$0{,}63\,\mu\text{V}$`, r`$6{,}3\text{ V}$`],
              2, r`$U_H = \frac{2\times0{,}5}{10^{29}\times1{,}6\times10^{-19}\times10^{-4}} = \frac{1}{1{,}6\times10^{6}} \approx 6{,}3\times10^{-7}\text{ V} = 0{,}63\,\mu\text{V}$ : très faible dans un métal (beaucoup de porteurs).`,
              r`$nqb = 10^{29}\times1{,}6\times10^{-19}\times10^{-4} = 1{,}6\times10^{6}$.`)),
        ],
      }),
    ],
  },
];
